window.__HOT_STORIES__ = {"schemaVersion":1,"updatedAt":"2026-11-13T19:50:31.475Z","stories":{"d01448e7-e6ef-4224-9e13-5f4b350dd6ed":{"publicId":"d01448e7-e6ef-4224-9e13-5f4b350dd6ed","title":"黄仁勋辞任英伟达CEO并退出董事会","status":"active","sourceCount":23,"reportCount":67,"firstReportAt":"2026-10-29T13:42:38.000Z","latestAt":"2026-11-13T04:17:46.000Z","latest":"黄仁勋辞任英伟达 CEO 全时间线复盘：两桩风波、接班人与 33 年生涯","digest":"英伟达董事会11月12日宣布，联合创始人、总裁兼CEO黄仁勋辞去总裁、CEO及董事职务，即刻生效，结束33年执掌。此前他承认与Megaspeed前高管Alice Huang的婚外情，美国情报界认为后者为中国国家安全部招募的间谍；《纽约时报》又曝出他与一名直接下属的第二段婚外情。董事会任命CFO Colette Kress为临时CEO，并启动内外部继任者遴选，前Synopsys CEO Harvey Jones出任公司首任董事长。\n\n董事会此前于周末启动独立调查，并称无理由认为国家安全或公司机密受损；《华尔街日报》随后报道董事会接近决定是否罢免黄仁勋。消息公布后，英伟达股价一度下跌13%至14%，市值回落至4万亿美元以下。\n\n事件还牵出芯片出口争议：The Information报道称Alice Huang相关网络向中国买家转手约75亿美元英伟达硬件；众议院中国特设委员会主席Moolenaar要求英伟达任命把国家安全置于首位的领导层，并推动年底国防授权法案通过出口管制立法。","digestUpdatedAt":"2026-11-13T12:42:36.675Z","reports":[{"id":"cs8aaqi9s05ph4pos2vguvohq","title":"Ed Zitron 长文解析 NVIDIA 走私指控与其历史争议","summary":"Ed Zitron 在付费长文中分析围绕 NVIDIA 的 GPU 走私指控网络，并引用 Culper Research 2026 年 5 月报告称相关出货可能占其 2026 财年营收超 20%（逾 430 亿美元）。","sourceName":"Ed Zitron 长文 / Where’s Your Ed At（RSS）","firstParty":false,"publishedAt":"2026-11-13T18:19:39.000Z","url":"https://www.wheresyoured.at/hg-megaspeed/"},{"id":"il5gmcwg4dn1n3sj5vl2bsuij","title":"黄仁勋丑闻时间线：婚外情、疑似中国间谍与辞任英伟达 CEO","summary":"英伟达联合创始人黄仁勋在承认婚外情后辞去 CEO 一职，CFO Colette Kress 出任临时 CEO。美方怀疑其情人之一、Megaspeed 高管 Alice Huang 为中国间谍，该公司两年内采购了价值 48 亿美元的英伟达芯片。路透社与《纽约时报》还报道了另外两段婚外情，美国国会已就芯片对华销售展开调查并要求黄仁勋作证。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-13T15:58:00.000Z","url":"https://techcrunch.com/2026/11/13/nvidia-ceo-jensen-huangs-affair-with-alleged-chinese-spy-a-timeline/"},{"id":"wkxqhc700pv5zgpew0cj5zyec","title":"Vergecast 播客解读黄仁勋辞任 NVIDIA CEO 后的连锁影响","summary":"The Vergecast 播客中 David Pierce 与 Nilay 梳理 NVIDIA CEO 黄仁勋周四辞职事件，并讨论后续可能展开的更大故事：NVIDIA 在中国的业务、美国政府的态度，以及整个 AI 行业的稳定性。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-13T14:47:16.000Z","url":"https://www.theverge.com/podcast/1032866/jensen-huang-nvidia-china-trump-vergecast"},{"id":"se0y4v3gihr6s0jmrc5vuv1zo","title":"AINews：黄仁勋辞任 NVIDIA CEO，Colette Kress 出任临时 CEO","summary":"Latent Space 的 AI 新闻日报头条是 NVIDIA 宣布黄仁勋在任职 33 年后辞去 CEO、总裁和董事职务，CFO Colette Kress 出任临时 CEO，SEC 文件显示董事会于 11 月 11 日接受辞呈，此前董事会已就 NYT 报道的绯闻事件展开独立调查。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-11-13T09:04:13.000Z","url":"https://latent.space/p/ainews-jensen-huang-resigns-after-33-years-leading-nvidia/"},{"id":"c38th8p4klxei4v40fxntey09","title":"黄仁勋辞任英伟达 CEO 全时间线复盘：两桩风波、接班人与 33 年生涯","summary":"11 月 12 日英伟达公告黄仁勋辞去总裁、CEO 和董事职务，即刻生效，未提原因；股价当日跌 13%，市值回落至 4 万亿美元以下，CFO 科莱特·克雷斯临时接任，哈维·琼斯成为公司 33 年来首位董事长。","sourceName":"X：卡尔的 AI 沃茨 (@aiwarts)","firstParty":false,"publishedAt":"2026-11-13T04:17:46.000Z","url":"https://x.com/aiwarts/status/2121095150114140317"},{"id":"sntaq2q8jo5gkp6hpgn0wy7g6","title":"Rohan Paul 日报：黄仁勋结束 33 年任期辞任 Nvidia CEO，Colette Kress 任临时 CEO","summary":"Rohan Paul 发布日报称，黄仁勋辞任 Nvidia CEO，结束 33 年任期，CFO Colette Kress 出任临时 CEO。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-13T02:05:59.000Z","url":"https://x.com/rohanpaul_ai/status/2121061984896708744"},{"id":"yb6o3s9lyxkb8xf7ykhrj3cr1","title":"黄仁勋辞任 Nvidia CEO，Casey Newton 撰文评析硅谷创始人崇拜的终结","summary":"Nvidia 于周四宣布 CEO 黄仁勋辞职，CFO Colette Kress 暂代 CEO，此前纽约时报曝光其第二段婚外情，路透社随后披露第三段。作者 Casey Newton 评析其职业生涯，指出硅谷创始人崇拜带来的两大问题，包括富豪寡头化和 key-man 风险，并称黄仁勋没有继任计划。","sourceName":"Platformer（热点 RSS）","firstParty":false,"publishedAt":"2026-11-13T01:43:23.000Z","url":"https://www.platformer.news/jensen-huang-resigns-founder-cult-accountability/"},{"id":"y51nb19h2bj96to0swwkv57oy","title":"黄仁勋辞任英伟达CEO：作者梳理14天时间线与33年生涯","summary":"11月12日英伟达公告黄仁勋辞去总裁、CEO和董事职务，股价当日跌13%，市值跌回4万亿美元以下，CFO科莱特·克雷斯临时接任。","sourceName":"公众号：卡尔的AI沃茨","firstParty":false,"publishedAt":"2026-11-13T01:03:00.000Z","url":"https://mp.weixin.qq.com/s/RB5f6wfZgI46D8ux_vK5LA"},{"id":"uef3cjv8f2j9x82ncz5frcfjg","title":"黄仁勋辞去英伟达总裁与CEO职务，卡兹克梳理事件始末","summary":"作者梳理黄仁勋辞去英伟达总裁、首席执行官和董事职务的来龙去脉，从2022年美国对A100、H100等芯片禁售写起，串起Megaspeed、黄乐与黄仁勋的关联、75亿美元芯片交易指控、《纽约时报》与The Information的系列调查报道，到11月12日晚公告辞职的14天时间线，并附带股价开盘下跌14个点等反应。","sourceName":"X：卡兹克 (@Khazix0918)","firstParty":false,"publishedAt":"2026-11-13T00:29:40.000Z","url":"https://x.com/Khazix0918/status/2121037747259625601"},{"id":"hqidckwtzcu63rwc19czidjld","title":"黄仁勋辞去英伟达 CEO，Hugging Face CEO 德朗格表态继续力挺开源 AI","summary":"黄仁勋于 11 月 12 日辞去英伟达总裁、CEO 及董事职务，即刻生效，CFO 科莱特·克雷斯出任临时 CEO，公司启动新 CEO 遴选。Hugging Face CEO 德朗格在领英称这是令人难过的一天，表示将比以往更努力捍卫开源人工智能。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-12T23:56:58.007Z","url":"https://www.ithome.com/1/026/469.htm"},{"id":"t86m3q7vdlqmvm2zmx91vps5a","title":"黄仁勋辞去英伟达总裁兼CEO，作者梳理14天风波始末","summary":"英伟达公告黄仁勋辞去总裁、CEO和董事职务，即刻生效，股价开盘下跌14个点。作者依据《纽约时报》、The Information 等报道梳理脉络：从2022年A100、H100对华禁售，到 Megaspeed 采购争议、黄乐被情报机构认定涉间谍活动，再到婚外情曝光后董事会于10月29日起14天内收网，黄仁勋在英伟达33年的时代就此结束。","sourceName":"公众号：数字生命卡兹克","firstParty":false,"publishedAt":"2026-11-12T23:56:00.000Z","url":"https://mp.weixin.qq.com/s/ToplAo9NHP356Fu-hbYlsg"},{"id":"ey8wwzav6ohoxh11jw491kcjg","title":"黄仁勋辞职引发对 Nvidia 开源 AI 战略延续性的疑问","summary":"Nvidia CEO 黄仁勋周四因承认与一名涉嫌中国间谍者的婚外情而辞职，引发对其开源 AI 支持路线能否延续的疑问。他此前推动 Nemotron 开源模型、支持收购 Hugging Face 的 130 亿美元交易，并牵头的 25 家公司联名信反对政府过度限制开源权重模型；CFO Colette Kress 已出任临时 CEO。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T18:39:23.000Z","url":"https://techcrunch.com/2026/11/12/jensen-huangs-exit-puts-nvidias-support-for-open-source-in-question/"},{"id":"n73ab4h9gqlu6ucv69ynzxln4","title":"SemiAnalysis 分析黄仁勋辞任 Nvidia CEO 背后的出口管制博弈","summary":"SemiAnalysis 发表长文分析黄仁勋不再担任 Nvidia CEO 一事，认为其去职与美国情报界推动、针对中国远程访问 GPU 的 RASA 法案推进有关。","sourceName":"SemiAnalysis 长文 RSS（RSS）","firstParty":false,"publishedAt":"2026-11-12T18:06:26.000Z","url":"https://newsletter.semianalysis.com/p/nvidia-and-the-world-without-jensen"},{"id":"licdk6vosezxouovor3gvtcpe","title":"The Verge 分析黄仁勋辞职与 Nvidia 芯片走私疑云","summary":"The Verge 作者 Elizabeth Lopatto 分析 Nvidia 宣布黄仁勋辞职一事，认为第二桩婚外情只是导火索，真正原因或与芯片走私指控有关。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T17:44:33.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1032069/jensen-huang-resignation-affair-chips-smuggling"},{"id":"rda6uss1k4k96ygzfl7a3byk0","title":"美众议院中国特设委员会主席 Moolenaar 就黄仁勋辞任 NVIDIA 发表声明","summary":"美众议院中国特设委员会主席 Rep. John Moolenaar 就黄仁勋辞任 NVIDIA 发表声明，称其被解职是一个本可避免的不幸结局。他表示 NVIDIA 现在必须改变公司治理方式，任命把国家安全置于最优先的领导层，并称国会应尽快在年底国防授权法案中通过两党出口管制立法。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-12T17:27:52.000Z","url":"https://x.com/rohanpaul_ai/status/2120931596396335208"},{"id":"sowwn4rv7ggtd41l0d469f1id","title":"Jensen Huang 被 Nvidia 董事会罢免 CEO 后，可能冲击 AI 行业的五个方面","summary":"Nvidia 董事会于周四罢免 CEO Jensen Huang，起因是他承认婚外情，且其中一名对象被美国政府怀疑为中国间谍、并任职于涉嫌走私 Nvidia 芯片的新加坡 neocloud。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T16:32:33.000Z","url":"https://techcrunch.com/2026/11/12/five-ways-jensen-huangs-ouster-from-nvidia-could-damage-the-ai-industry/"},{"id":"o8bau0c6koaa9ibvrxjfpl32e","title":"黄仁勋辞任英伟达CEO：中国究竟想从他身上得到什么？","summary":"黄仁勋辞去英伟达CEO职务，此前其与一名被指为中国间谍的女性存在关联的传闻持续发酵。布鲁金斯学会中国中心研究员Kyle Chan在Decoder访谈中分析，中国接近黄仁勋的重点可能不在GPU设计细节，而在于他对特朗普的直接影响力和美国政策制定过程的信息。访谈还讨论了DeepSeek R1、CUDA生态及华为等国产AI芯片替代路径。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T16:30:00.000Z","url":"https://www.theverge.com/podcast/1031260/nvidia-jensen-huang-resign-china-spy-scandal-ai-chips-trump"},{"id":"toq4wymx9maq8lhhz8jryi0sv","title":"黄仁勋辞职后，Nvidia 与 AI 热潮的未来走向分析","summary":"Azeem Azhar 分析黄仁勋辞任 Nvidia CEO 后的影响，CFO Colette Kress 将临时接任。他指出 Nvidia 五年间售出近 1400 万颗旗舰 AI 芯片、占市场 85%，并向 neocloud 提供财务担保、过去一年在欧洲投资近 100 亿美元；与乔布斯离任时不同，公司没有准备好的继任者，而黄仁勋本人一直是 AI 生态的关键纽带。","sourceName":"Azeem Azhar：Exponential View（RSS）","firstParty":false,"publishedAt":"2026-11-12T16:19:28.000Z","url":"https://www.exponentialview.co/p/jensen-huang-and-the-future-of-the"},{"id":"jferw1o1blgp1kv5z4no8qb5s","title":"NVIDIA CEO 黄仁勋辞职，CFO Colette Kress 出任临时 CEO","summary":"NVIDIA 联合创始人黄仁勋于当天早晨辞去 CEO 和董事职务，此前董事会对其与直属下属的多段婚外情及一名涉嫌中国间谍的调查展开调查。董事会任命任职超过 13 年的 CFO Colette Kress 为临时 CEO，Harvey Jones 出任首任董事会主席并致信员工；Kress 在首封临时 CEO 信中称这是一段极其艰难的时期，公司将于 11 月 18 日 9am PT 举行全员会议。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T15:48:12.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1032028/read-nvidias-internal-emails-jensen-huang"},{"id":"l7dv9twcz25784wh4ttbhxm78","title":"Nvidia CEO 黄仁勋辞职，CFO Colette Kress 出任临时 CEO","summary":"Nvidia 董事会宣布，执掌公司 33 年的联合创始人兼 CEO 黄仁勋辞去总裁、CEO 及董事职务，即刻生效。辞职发生在媒体报道他与一名涉嫌中国间谍及其一位直接下属有婚外情之后，公司此前从未设立继任计划。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T15:37:29.000Z","url":"https://techcrunch.com/2026/11/12/jensen-huang-is-out-at-nvidia-who-is-colette-kress-his-interim-replacement/"},{"id":"xe5jgbho8qhh6ahx1353wdycv","title":"NVIDIA 官宣 CEO 过渡，发布声明链接","summary":"NVIDIA Newsroom 宣布 CEO 过渡，附官方新闻稿链接 https://nvidianews.nvidia.com/news/nvidia-announces-ceo-transition。转发者 X.PIN 仅以“Such an era!”感叹，未补充细节。","sourceName":"X：X.PIN (@thexpin)","firstParty":false,"publishedAt":"2026-11-12T14:59:46.000Z","url":"https://x.com/thexpin/status/2120894325370577402"},{"id":"aol3stj5rjrl9sq35s3d4fzt6","title":"《大西洋月刊》谈黄仁勋在华盛顿的影响力","summary":"《大西洋月刊》有篇有意思的文章。\n\n这期节目展示了黄仁勋的影响力在华盛顿扩散得有多广。\n\n据文章称，在报道公开前数月，警告就已传达至政府高层官员。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-12T14:53:11.000Z","url":"https://x.com/rohanpaul_ai/status/2120892671178973263"},{"id":"cq52ebt0mx19monojyqyuxdo1","title":"黄仁勋辞任 Nvidia CEO，CFO Colette Kress 接任临时负责人","summary":"Gary Marcus 称黄仁勋已辞去 Nvidia CEO 职务，董事会推动其离任，由 CFO Colette Kress 出任临时负责人。他表示消息公布后 Nvidia 股价跌幅从盘前 8% 扩大到开盘时的 13%，并担心黄仁勋主导的循环融资可能崩塌，以及此前承诺投入 Anthropic 的数十亿美元 IPO 资金是否兑现成为焦点。他同时列举了国会调查、中国市场影响和政治层面的后续不确定性。","sourceName":"Gary Marcus：The Road to AI We Can Trust（RSS）","firstParty":false,"publishedAt":"2026-11-12T14:44:04.000Z","url":"https://garymarcus.substack.com/p/jensen-huang-resigns"},{"id":"m76r4bnrvb21vkm8wn2khk0jr","title":"Kate Clark 转发 WSJ 报道称 Nvidia 正准备罢免 CEO 黄仁勋并征集信源","summary":"记者 Kate Clark 分享 WSJ 报道链接，该报道称 Nvidia 正准备罢免 CEO 黄仁勋。她同时留下 Signal 联系方式 415-409-9095，征集关于此事对私募市场、交易撮合、融资及 AI 行业连锁影响的爆料与讨论。","sourceName":"X：Kate Clark (@KateClarkTweets)","firstParty":false,"publishedAt":"2026-11-12T14:39:04.000Z","url":"https://x.com/KateClarkTweets/status/2120889116250288597"},{"id":"xraa42gmh7ndg2a3wvenh2rnv","title":"黄仁勋丑闻时间线：承认婚外情、辞去英伟达 CEO","summary":"英伟达联合创始人黄仁勋承认婚外情后，于 11 月 12 日辞去 CEO 一职，CFO Colette Kress 出任临时 CEO。此前有报道称其婚外情对象 Alice Huang 被美方怀疑为中国间谍，另一段与英伟达副总裁 Kimberly Powell 的婚外情也被《纽约时报》曝出。英伟达董事会已启动独立调查，美国国会还计划传唤黄仁勋作证。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T14:30:01.000Z","url":"https://techcrunch.com/2026/11/12/nvidia-ceo-jensen-huangs-affair-with-alleged-chinese-spy-a-timeline/"},{"id":"hfrol86d5xxs0jzhviul1dlof","title":"黄仁勋辞任 Nvidia CEO 并退出董事会，任职超 33 年","summary":"黄仁勋辞去 Nvidia CEO 并退出董事会，结束超过 33 年的执掌；CFO Colette Kress 出任临时 CEO，董事 Harvey Jones 成为 Nvidia 首位董事会主席。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-12T14:16:34.000Z","url":"https://x.com/rohanpaul_ai/status/2120883455689170968"},{"id":"a8s824c3xp0bij54fi8q9psm7","title":"黄仁勋因间谍丑闻辞去 Nvidia CEO 职务，公司市值蒸发 1.4 万亿美元","summary":"黄仁勋于 2026 年 11 月 12 日立即辞去 Nvidia CEO、总裁及董事会成员职务，此前《华尔街日报》报道董事会因两段婚外情（其中一段涉及疑似中国间谍）计划将其解雇。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-12T14:11:40.000Z","url":"https://the-decoder.com/jensen-huang-resigns-as-nvidia-ceo-after-espionage-scandal-wipes-out-1-4-trillion-in-market-value/"},{"id":"b79vyi335xo1r2u8eiza66a8r","title":"Nvidia CEO 黄仁勋因绯闻与间谍丑闻辞职，CFO Colette Kress 出任临时 CEO","summary":"Nvidia 董事会宣布，联合创始人、总裁兼 CEO 黄仁勋在两段婚外情报道曝光后辞职，即日生效，自 2013 年起任职的 CFO Colette Kress 被任命为临时 CEO，并任命前 Synopsys CEO Harvey C. Jones 为公司历史上首任董事长。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T13:53:16.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1031689/jensen-huang-nvidia-ceo-resigns"},{"id":"qsbjbz754aodhcijq56puh6va","title":"NVIDIA 宣布 CEO 变动：Jensen Huang 辞任，CFO Colette Kress 出任临时 CEO","summary":"NVIDIA 董事会宣布 Jensen Huang 即刻辞去总裁、CEO 及董事职务，CFO Colette Kress 被任命为临时 CEO，直至选定永久继任者，董事会已启动内外部人选遴选。","sourceName":"NVIDIA：Newsroom（RSS）","firstParty":true,"publishedAt":"2026-11-12T13:48:00.000Z","url":"https://nvidianews.nvidia.com/news/nvidia-announces-ceo-transition"},{"id":"mo0q79b9m2krn2wunnm5blw48","title":"郭明錤谈黄仁勋出轨丑闻：英伟达或需降低对其决策依赖并布局接班计划","summary":"天风国际分析师郭明錤在 X 平台发文评黄仁勋出轨丑闻，认为黄的价值在于把工程团队认为可行的技术转化为全公司愿意投入资源、承担风险并交付的产品，带动供应链订单能见度与竞争对手跟进。他从公开信息判断黄仁勋似乎很难全身而退，建议英伟达阶段性降低对黄个人的决策依赖并布局接班计划，其后续新品研发效率与竞争对手回应将是观察 AI 产业发展和投资趋势的重点。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-12T04:15:28.377Z","url":"https://www.ithome.com/1/026/027.htm"},{"id":"b0is4k552g0vme6l74e8z1lhw","title":"Gary Marcus 评 WSJ 报道 Nvidia 正准备解雇 CEO 黄仁勋","summary":"Gary Marcus 引述《华尔街日报》报道称，Nvidia 正准备解雇 CEO 黄仁勋，起因是公司调查其与一名被指为中国间谍的女性的婚外情。作者认为黄仁勋是整个循环融资的主导者，若其离任这些安排可能崩塌，并质疑代理 CEO 是否会兑现 Nvidia 承诺给 Anthropic 的数十亿美元 IPO 投资；盘后股价已下跌。","sourceName":"Gary Marcus：The Road to AI We Can Trust（RSS）","firstParty":false,"publishedAt":"2026-11-11T23:53:06.000Z","url":"https://garymarcus.substack.com/p/jensen-is-reportedly-about-to-get"},{"id":"i1hiziogjyvjvclikqylj5p2p","title":"黄仁勋丑闻时间线：婚外情、疑似中国间谍与Nvidia董事会罢免传闻","summary":"Nvidia CEO 黄仁勋公开承认婚外情，其绯闻对象、Megaspeed 高管 Alice Huang 被美国官员怀疑是中国间谍。纽约时报称黄仁勋还与直接向他汇报的 Nvidia 医疗健康副总裁 Kimberly Powell 存在婚外关系，Nvidia 董事会正准备罢免他，股价盘后下跌。国会计划传唤黄仁勋就此事作闭门说明。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-11T23:50:00.000Z","url":"https://techcrunch.com/2026/11/11/nvidia-ceo-jensen-huangs-affair-with-alleged-chinese-spy-a-timeline/"},{"id":"aoxmmcsudy1gf9xmti7slu1wd","title":"WSJ 报道 Nvidia 董事会接近决定是否罢免 CEO 黄仁勋","summary":"WSJ 报道，Nvidia 董事会此前公开支持黄仁勋，如今接近决定是否罢免这位创始人 CEO。起因是黄仁勋与一名被指为中国情报人员的女子交往，随后又曝出与一名 Nvidia 员工的第二段婚外情；周日开始独立调查时董事会表示没有理由认为 Nvidia 机密泄露。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-11T23:43:05.000Z","url":"https://x.com/rohanpaul_ai/status/2120663635479625930"},{"id":"vyp3tt502r42oxb18k4b663hi","title":"黄仁勋\"蜜罐\"丑闻背后：半导体行业高管行为问题是否更普遍？","summary":"Heron Intelligence CEO Nate Singer 在黄仁勋\"蜜罐\"丑闻后表示，半导体行业存在多起未曝光的类似高管行为案例，他已看到至少三份相关报告，并怀疑更多案例未被上报。Singer 称业内许多高管知晓此类行为却实际上予以纵容，涉事人员\"已嵌入这些公司\"。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-11T16:16:07.000Z","url":"https://techcrunch.com/2026/11/11/is-jensen-huangs-bad-behavior-more-commonplace-than-it-seems/"},{"id":"x7y9eom67zy7rs1vzn6sijizd","title":"ElevenLabs 纽约峰会发布多项更新：Interaction Engine、ElevenAgents 升级与 ElevenAI","summary":"ElevenLabs 在纽约峰会宣布多项发布，定位为构建 AI 的交互层。","sourceName":"ElevenLabs：Blog（网页）","firstParty":true,"publishedAt":"2026-11-11T12:00:00.000Z","url":"https://elevenlabs.io/blog/nyc-summit"},{"id":"k0s9asp7ahp38drtj69gi5lye","title":"英伟达CEO绯闻或波及芯片业","summary":"《华尔街日报》：出口管制支持者以这一事件为证，佐证他们对漏洞的警告\n\n“英伟达CEO的绯闻可能给这家全球顶级芯片设计公司乃至整个行业带来商业后果。\n\n尽管许多议员在提出法案时都提到了英伟达，但这些提案可能伤及其他芯片公司，包括英伟达的竞争对手AMD，甚至微软和OpenAI这类正试图在海外建设数据中心的科技巨头。”","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-11T05:42:06.000Z","url":"https://x.com/rohanpaul_ai/status/2120391599264063648"},{"id":"ggty0pffnixa85pbbyxk826ug","title":"FT 曝 Alice Huang 借 Megaspeed 走私 Nvidia 芯片","summary":"FT 发文披露 Alice Huang 与秘密男友兼商业伙伴 Kang Wei 运营新加坡公司 Megaspeed，用阿里巴巴的资金向被美国出口规则限制的中国客户出租 Nvidia 芯片。她改名 Alice Wong 并把妹妹安插进公司董事会以隐藏实际控制人，美国情报部门认为她在接近黄仁勋期间为中国从事间谍活动，新加坡调查 Megaspeed 芯片走私后她已消失。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-10T20:28:14.000Z","url":"https://x.com/rohanpaul_ai/status/2120252212551332311"},{"id":"lmoed4ffl87b0bpfvt1lzsp1g","title":"黄仁勋被曝与疑似中国间谍有染，或危及美国 AI 领先地位","summary":"英伟达 CEO 黄仁勋承认与一名疑似中国间谍的女性有染，事件可能冲击整个美国 AI 产业并危及国家安全。专家向 The Verge 表示，若中国借此获得英伟达芯片，美国在 AI 上的领先优势\"可能在数周或数月内消失\"；与这名疑似间谍有关联的公司据称已促成至少 70 亿美元的英伟达芯片销往中国。消息曝光后英伟达股价下跌。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-10T19:04:05.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1031063/jensen-huang-ai-race-us-china-spy"},{"id":"gqzca7y2h3m9p0fxtj60m4i1t","title":"Ed Zitron 长文剖析黄仁勋丑闻与 NVIDIA 疑似借 Megaspeed 向中国走私 GPU","summary":"Ed Zitron 长文梳理黄仁勋承认与 Megaspeed CEO Alice Huang 的婚外情事件，并整合 Bloomberg、纽约时报、金融时报与 Culper Research 的报道，指 Megaspeed 疑似作为转口实体将 NVIDIA GPU 非法流入中国。","sourceName":"Ed Zitron 长文 / Where’s Your Ed At（RSS）","firstParty":false,"publishedAt":"2026-11-10T17:43:27.000Z","url":"https://www.wheresyoured.at/jensens-bizarre-adventure/"},{"id":"nakew5hejxet8jnydy0h37b1q","title":"英伟达 CEO 黄仁勋承认婚外情，涉疑似中国间谍事件时间线","summary":"英伟达 CEO 黄仁勋 11 月 8 日向员工公开承认婚外情，并称此事关联新闻报道中的国家安全担忧，英伟达董事会已启动独立调查，公司股价次日下跌超 5%。美方官员认为其婚外情对象、Megaspeed 高管 Alice Huang 为中国间谍，Megaspeed 过去两年据称采购了 48 亿美元英伟达芯片。三名共和党委员会主席已要求黄仁勋就中国获取美国技术风险进行闭门简报。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-10T17:04:19.000Z","url":"https://techcrunch.com/2026/11/10/nvidia-ceo-jensen-huangs-affair-with-alleged-chinese-spy-a-timeline/"},{"id":"f1z5v9nswvnu4w2plxd4tg22t","title":"The Information 报道称与英伟达 CEO 黄仁勋相关人士向中国买家转手 75 亿美元硬件","summary":"据 The Information 报道，与英伟达 CEO 黄仁勋有染的 Alice Huang（无亲属关系）与丈夫和姐姐在中国和新加坡建立采购网络，涉资 75 亿美元。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-10T14:33:22.000Z","url":"https://x.com/rohanpaul_ai/status/2120162909422780789"},{"id":"z68n80gno9fz2iwdgj4wr9tyw","title":"黄仁ullah承认婚外情，Nvidia 董事会调查对方是否为中国国安部工作","summary":"周日黄仁ullah向全体 Nvidia 员工发邮件承认与 Megaspeed 高管 Alice Huang 的婚外情，其董事会已启动调查，核查该女士是否为中国国家安全部工作。Megaspeed 这家被怀疑向中国走私 Nvidia 芯片的新加坡云公司仍在继续采购芯片。","sourceName":"ChinaTalk（RSS）","firstParty":false,"publishedAt":"2026-11-10T12:28:08.000Z","url":"https://www.chinatalk.media/p/the-spy-who-leased-me"},{"id":"kci32x4hgxrdl0v5o4xrjlxri","title":"The Verge 梳理黄仁勋与 Megaspeed 高管丑闻对 Nvidia 出口管制游说的影响","summary":"The Verge 依据《纽约时报》等报道梳理 Nvidia CEO 黄仁勋与新加坡云服务商 Megaspeed 高管 Alice Huang 的婚外情风波。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T23:51:58.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1030328/what-could-china-get-from-jensen-huang"},{"id":"t5mqlkgq1zlspdsk77jrx1ho5","title":"Trump 就间谍指控表态支持 Nvidia CEO 黄仁勋","summary":"Trump 在与 Nvidia CEO 黄仁勋就间谍指控谈话后公开为其辩护，称黄仁勋告诉他从不认识那名女性是间谍，并表示相信他。Trump 称黄仁勋是高素质的人，提到其芯片领先十年、因复杂度难以被复制，并称相信黄仁勋因家人而深感痛苦。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-09T23:12:09.000Z","url":"https://x.com/rohanpaul_ai/status/2119931075325759514"},{"id":"lzsihkjga6ini01aqrzcuvtaw","title":"Nvidia CEO 黄仁勋因间谍与婚外情丑闻辞职，CFO Colette Kress 出任临时 CEO","summary":"Nvidia CEO、总裁兼联合创始人黄仁勋在承认与 Megaspeed 高管 Alice Huang 的婚外情后辞职，CFO Colette Kress 出任临时 CEO。《纽约时报》周三报道称，还存在另一段与直接向他汇报的 Nvidia 高管的婚外情证据，当晚董事会会议以黄仁勋辞职告终。此前有报道指出，美国情报部门自去年起认定 Alice Huang 为中国国家安全部间谍。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T23:07:59.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1030422/nvidia-jensen-huang-ai-china-alice-huang"},{"id":"zqvokl37rwbvoxzfk3c2v7964","title":"做空机构 Culper Research 曾在丑闻爆发前六个月提示 Nvidia CEO 与疑似中国间谍的关系","summary":"Nvidia 间谍丑闻爆发前六个月，做空机构 Culper Research 已在 5 月 13 日报告中质疑 CEO 黄仁勋与 Megaspeed 高管 Alice Huang 关系“异常密切”。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T22:46:09.000Z","url":"https://techcrunch.com/2026/11/09/a-short-seller-flagged-nvidia-ceos-ties-to-a-suspected-chinese-spy-six-months-before-the-scandal/"},{"id":"wtp3nz2jg6cfwlvn12lqrucy7","title":"黄仁勋因个人风波退出 ElevenLabs Summit 等演讲活动","summary":"TechCrunch 报道，Nvidia CEO 黄仁勋退出本周三在纽约举行的 ElevenLabs Summit，并取消了包括 Anthropic CEO Forum 在内的其他演讲安排，ElevenLabs 周一已确认。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T20:09:06.000Z","url":"https://techcrunch.com/2026/11/09/jensen-huang-pulls-out-of-elevenlabs-summit-amid-nvidia-controversy/"},{"id":"jg700hxd681xxb0f0r5fn03fc","title":"黄仁勋与疑似中国间谍的婚外情令 Nvidia 中国业务承压","summary":"《金融时报》报道 Nvidia CEO 黄仁勋与 Nvidia 客户 Megaspeed 前高管 Alice Huang 存在婚外情，美国情报官员认为后者被中国情报部门招募以影响芯片出口限制。黄仁勋已承认此事并向公司致歉，Nvidia 独立董事正联合外部律师调查，国会也要求作出解释。截至 7 月 26 日的三个月内，Nvidia 来自中国总部客户的收入为 79 亿美元，约占总营收 8%。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T18:09:52.000Z","url":"https://techcrunch.com/2026/11/09/jensen-huangs-affair-with-alleged-chinese-spy-puts-nvidias-china-ambitions-under-scrutiny/"},{"id":"q8qzxski2nw3jgr77q1mwpskg","title":"Nvidia CEO 黄仁勋陷间谍丑闻风波：The Verge 分析其公司结构与 AI 生态风险","summary":"The Verge 作者评述 The New York Times 报道的 Nvidia CEO 黄仁勋与 Megaspeed 高管 Alice Huang 的关系风波，后者被指被中国国家安全部招募，Megaspeed 曾购买 48 亿美元被限制出口的 Nvidia 芯片。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T17:36:08.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1029990/jensen-huang-the-spy-who-loved-me"},{"id":"mkmn0bduza8asy7b56mygydl2","title":"Nvidia CEO 黄仁勋承认婚外情，董事会启动独立调查","summary":"Nvidia CEO 黄仁勋在内部信中承认婚外情，此前 FT 报道称美国情报界认为其涉事对象 Alice Huang 为中国国家安全部招募的间谍。Nvidia 董事会将启动独立调查，称无理由认为国家安全或公司机密受损，黄仁勋承诺全力配合。Nvidia 法兰克福上市股票周一早盘跌超 6%。","sourceName":"Ars Technica：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T15:23:20.000Z","url":"https://arstechnica.com/tech-policy/2026/11/ceo-jensen-huang-admits-affair-as-nvidia-probes-possible-chinese-espionage/"}]},"2ff1f46f-7e98-4965-a5b2-87329632ca5d":{"publicId":"2ff1f46f-7e98-4965-a5b2-87329632ca5d","title":"Google 发布 Gemini 4 Hydrogen，接入搜索与编程工具","status":"active","sourceCount":25,"reportCount":48,"firstReportAt":"2026-11-11T16:00:00.000Z","latestAt":"2026-11-13T09:45:48.000Z","latest":"Google 发布 Gemini 4 Hydrogen，速度比 Gemini 3.8 Flash 快 2.5 倍","digest":"Google DeepMind 发布 Gemini 4 Hydrogen，定位为快速执行日常编码与智能体工作流的模型，与主打深度推理的 Carbon、Argon 同属 Gemini 4 系列。Google 称这是 Search 迄今最大的模型升级，已向全球所有用户开放；该模型同时成为 Gemini Managed Agents 中 Antigravity 智能体的默认模型，并已上线 Cursor 和 Cognition 的 Devin Desktop、Devin CLI，OpenClaw 也称已可使用。Ars Technica 称它取代了此前广泛使用的 Gemini 3.8 Flash，且上线即开放，不像 Argon、Carbon 那样分阶段推送。\n\n使用范围按用户类型区分：所有用户可在 Gemini 应用、Google Search 和 Google AI Studio 访问；付费 Google AI Pro 和 Ultra 订阅者还可在 Google Antigravity、Chrome 中的 Gemini 和 Google Sheets 中的 Gemini 使用；开发者和企业可通过各档 Gemini API、Android Studio 及 Gemini for business 使用。免费用户在 Gemini 应用中需通过自动模型选择，在适合该提示词的场景下才会用到 Hydrogen。定价为 100 万 token 上下文窗口内统一计价：输入每百万 token 1.50 美元，输出每百万 token 7.50 美元。\n\n第三方评测机构 Artificial Analysis 称，该模型新增的 xhigh 推理档在 Intelligence Index 得 54 分，比 Claude Sonnet 5.5 (max) 和 GPT-6.1 Sol (max) 低 1 分；每任务成本约为 Sonnet 的 32%，但约为 GPT-6.1 Sol 的 2.5 倍。该机构另称 Hydrogen 在 AA-Robotics v0.1 中排第四，是排名最高的 Google 模型，落后于 Claude Fable 5.2、GPT-6 Astra 和 GPT-6.1 Sol。Cursor 称该模型在其默认 effort 下 CursorBench 得分 54.3%，高于 Gemini 3.8 Flash 的 39.6%；Cognition 称其在 FrontierCode 2.0 得 38.2%，仅次于 GPT-6.1 Sol；Arena 榜单显示 Gemini 4 Hydrogen (High) 首次进入 Code Arena: WebDev 第 10 名，得 1703 分。","digestUpdatedAt":"2026-11-13T15:34:22.296Z","reports":[{"id":"aharkngusk0no7dmgd0kg5x8u","title":"Google 发布 Gemini 4 Hydrogen，速度比 Gemini 3.8 Flash 快 2.5 倍","summary":"Google DeepMind 发布闭源模型 Gemini 4 Hydrogen，定位编码与智能体工作流，速度比 Gemini 3.8 Flash 快 2.5 倍，Terminal-Bench 4.1 得分 57%（3.8 Flash 为 18.2%）。","sourceName":"MarkTechPost（RSS）","firstParty":false,"publishedAt":"2026-11-13T09:45:48.000Z","url":"https://www.marktechpost.com/2026/11/13/google-gemini-4-hydrogen/"},{"id":"g1i3oaaq9yrtsm2toewsuhcwk","title":"Gemini 4 Hydrogen 发布并已可在 OpenClaw 中使用","summary":"OpenClaw 转发官方消息：Google 推出 Gemini 4 Hydrogen，一个为让 Gemini 4 面向所有人而构建的高能力、快速模型。该模型面向 Google AI Studio、Gemini API、Gemini for business、Gemini 应用、Google Search 的所有层级开放，付费 Google AI Pro + Ultra 订阅者还可在 Google Antigravity 中使用；作者称其已可在 OpenClaw 中使用。","sourceName":"X：OpenClaw (@openclaw)","firstParty":false,"publishedAt":"2026-11-13T04:31:12.000Z","url":"https://x.com/openclaw/status/2121098531205501401"},{"id":"jk2j1qrls5xbfylot1i4nudhj","title":"Gemini 3.8 Flash 与 Hydrogen 动画对比","summary":"🌵 一览从 Gemini 3.8 Flash 到 Hydrogen 的演进：@Bhavani_00007 在两者上运行了相同的动画 3D 沙漠牧场提示词，Hydrogen 在不到 1 分钟内让场景生动呈现。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-13T00:30:02.000Z","url":"https://x.com/Google/status/2121037841287249920"},{"id":"k5e9f5e3c6xe1zza3n896s48r","title":"Gemini 4 Carbon 与 Hydrogen 协作打造飞蛾动画","summary":"🦋 @thtbee_ 在 @Antigravity 中将我们最新的两个模型搭配使用，让一只绯红色飞蛾活了起来：\n\nGemini 4 Carbon 调度了一支由 Hydrogen 工作单元组成的 /swarm，创作出一段带有大气视觉效果与声音的交互式动画。\n\n随后，Hydrogen 还录制了演示视频。\nhttps://x.com/thtbee_/status/2120958666480513310/video/1","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-13T00:30:02.000Z","url":"https://x.com/Google/status/2121037839563730994"},{"id":"ezf7jqy3z5guwnvf7h2p8734y","title":"Google Antigravity 演示 Hydrogen 通勤场景","summary":"🌃 @kimmonismus 在 @Antigravity 中用高思考模式的 Hydrogen 打造了我们理想的通勤场景。\n\n欣赏这段穿越 Three.js 霓虹天际线的流畅飞行。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-13T00:30:01.000Z","url":"https://x.com/Google/status/2121037833699995729"},{"id":"u38hqxar8y2h8tqj2lrpmatbl","title":"Gemini 应用用 Hydrogen 设计 3D 锦鲤池","summary":"🐠@IamEmily2050 在 @Geminiapp 中使用 Hydrogen 设计了一个 3D 体素锦鲤池，配有红色宝塔、樱花和灯笼点缀的桥梁。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-13T00:30:01.000Z","url":"https://x.com/Google/status/2121037835629109486"},{"id":"lf2ylaegvpxzrjrjflaqjqiz2","title":"Google 展示 Gemini 4 Hydrogen 开放后用户的创意构建案例","summary":"Google 表示 Gemini 4 Hydrogen 已向所有人开放，并汇总了用户在 @GeminiApp、@Antigravity 和 @GoogleAIStudio 上基于模型实现的各类“what if”创意构建。帖中举例 @LuminaBench 制作的 3D 水上飞机从日出飞到夜晚的场景，并预告后续将分享更多作品。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-13T00:30:00.000Z","url":"https://x.com/Google/status/2121037830797271522"},{"id":"ajlka18ww5d31h5ezjf16r801","title":"Google 发布 Gemini 4 Hydrogen，Simon Willison 梳理 Gemini 4 定价并实测对比","summary":"Google 发布 Gemini 4 家族最低价型号 Gemini 4 Hydrogen，定价 $1.50/$7.50（每 M token 输入/输出），作者 Simon Willison 称 Gemini 4 定价令人困惑。","sourceName":"Simon Willison 博客","firstParty":false,"publishedAt":"2026-11-12T22:55:19.000Z","url":"https://simonwillison.net/2026/Nov/12/llm-gemini/"},{"id":"w61lggu0l1pijph9baxgv21z2","title":"Gemini 4 Hydrogen 用表格画动态风景","summary":"我们大多数人打开 Google Sheets 是为了做预算、跟踪表和表格。借助 Gemini 4 Hydrogen，我们想看看它能否反过来绘制一幅动态风景 🍃\n\n在 Google @Antigravity 中，Hydrogen 负责编写代码来绘制并动画化数千个单元格——创造出海岸列车、飘动的云朵和飘落的秋叶，并在电子表格内逐帧重新计算。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-12T22:17:02.000Z","url":"https://x.com/Google/status/2121004369617485896"},{"id":"dhccssumshi2lie122qh66tgp","title":"Google 发布 Gemini 4 Hydrogen，提升复杂问题理解并成为 AI Mode 默认模型","summary":"Google 发布 Gemini 4 Hydrogen 模型，称其能更好地处理多部分问题、难以理解的拼写错误和高度具体请求，可拆解问题并逐部分回答。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T21:55:32.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1032505/google-search-ai-mode-gemini-4-hydrogen"},{"id":"cy8ycgy2ijidcqfu9ubcc2kd2","title":"Gemini 4 Hydrogen 在 AA-Robotics 排名第四","summary":"Gemini 4 Hydrogen 是 AA-Robotics v0.1 上排名最高的 Google 模型，总排名第四，落后于 Claude Fable 5.2（75）、GPT-6 Astra（69）和 GPT-6.1 Sol（65）\n\nHydrogen 对自己的表现非常诚实，指出倒饮料时有一点洒出，整理积木时有一个盖子没盖好","sourceName":"X：Artificial Analysis (@ArtificialAnlys)","firstParty":false,"publishedAt":"2026-11-12T21:40:31.000Z","url":"https://x.com/ArtificialAnlys/status/2120995180891508833"},{"id":"zlbngirpqifhhi3bd5pbmixu4","title":"Gemini 4 Hydrogen 今日起向全球所有用户推送","summary":"Google Gemini 宣布 Gemini 4 Hydrogen 今日起向全球所有用户推送，覆盖桌面、移动和网页端。免费用户无需单独选择模型，当提示词适合该模型时可通过自动模型选择使用它，详情见 https://goo.gle/4AxH40q。","sourceName":"X：Gemini (@GeminiApp)","firstParty":false,"publishedAt":"2026-11-12T20:50:50.000Z","url":"https://x.com/GeminiApp/status/2120982674638864797"},{"id":"y0y7mh858hig08jz41nfdczcu","title":"Gemini 4 Hydrogen 实时模拟光折射","summary":"在完成创建交互式 3D 水和玻璃可视化工具的任务时，Gemini 4 Hydrogen 能够使用 WebGL2 和纯数学实时模拟光的折射、反射和色散。","sourceName":"X：Gemini (@GeminiApp)","firstParty":false,"publishedAt":"2026-11-12T20:49:58.000Z","url":"https://x.com/GeminiApp/status/2120982456203694352"},{"id":"u7yh59ito20pqcy3kfrg1jao9","title":"Google 发布 Gemini 4 Hydrogen，评测得分超过更大的 Argon","summary":"Google 发布 Gemini 4 Hydrogen，主打快速低价处理日常任务，在 Artificial Analysis Intelligence Index 上默认 high 档得 51 分、最高 xhigh 档得 54 分，超过 Gemini 4 Argon 的 50 分。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-12T19:58:43.000Z","url":"https://the-decoder.com/googles-gemini-4-hydrogen-outscores-the-bigger-argon-just-four-weeks-after-its-launch/"},{"id":"glx90o1i9stshq4vwsxdsguy5","title":"Google 发布 Gemini 4 Hydrogen 并将其接入 Search 提升复杂问题回答","summary":"Google 发布 Gemini 4 Hydrogen 模型并将其接入 Search，称这是 Search 迄今最大的一次模型改进。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T19:27:45.000Z","url":"https://techcrunch.com/2026/11/12/googles-latest-search-upgrade-promises-better-answers-to-your-most-complicated-questions/"},{"id":"w1u3ixmq8qb8g20v2o8yfebpw","title":"Google 在搜索中引入 Gemini 4 Hydrogen","summary":"Google 官方宣布 Gemini 4 Hydrogen 已进入 Google Search，并提供链接 goo.gle/4AqQVF5 供用户了解更多信息。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-12T19:23:35.000Z","url":"https://x.com/Google/status/2120960717071474748"},{"id":"pplqpkkb0a59joi6llhtmrgff","title":"Google Search 接入 Gemini 4 Hydrogen 并向全球用户推送","summary":"Google 宣布 Search 迎来迄今最大模型更新，接入 Gemini 4 Hydrogen，今日起向全球所有用户推出。更新包括更好理解多部分复杂问题、支持错别字并覆盖所有 AI Mode 语言；回答采用带图片、对比表的视觉化布局；升级 query fan-out，并行子主题查询以链接更多相关网页。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-12T19:23:34.000Z","url":"https://x.com/Google/status/2120960715011883148"},{"id":"r03z6qalcfw99hwf8jq8b5mxb","title":"Google 发布 Gemini 4 Hydrogen，取代 Gemini 3.8 Flash","summary":"Google 发布 Gemini 4 Hydrogen，取代生态内广泛使用的 Gemini 3.8 Flash，且开放程度远高于此前 Argon、Carbon 的分阶段策略，上线即对用户开放。","sourceName":"Ars Technica：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T19:23:03.000Z","url":"https://arstechnica.com/google/2026/11/google-rolls-out-gemini-4-hydrogen-finally-replacing-3-8-flash/"},{"id":"o8coj46233j11jhise87m8gza","title":"Gemini 4 Hydrogen (High) 登上 Code Arena: WebDev 第 10 名，得 1703 分","summary":"Arena 官方榜单显示，Google DeepMind 的 Gemini 4 Hydrogen (High) 首次进入 Code Arena: WebDev 排行第 10 名。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-12T19:05:40.000Z","url":"https://x.com/arena/status/2120956209725661670"},{"id":"qcfuv50f2bxz6tv32dtblc88x","title":"谷歌发布 Gemini 4 Hydrogen 模型，主打日常编程与智能体工作流","summary":"谷歌推出 Gemini 4 Hydrogen 模型，面向日常编码和智能体工作流，输入每百万 Tokens 1.50 美元、输出 7.50 美元，覆盖 100 万 Token 上下文无阶梯计价。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-12T18:50:00.073Z","url":"https://www.ithome.com/1/026/446.htm"},{"id":"uu2pim7p0lb9lhqcrvg7v3zgu","title":"Gemini 4 Hydrogen 上线 Devin","summary":"Gemini 4 Hydrogen 现已在 Devin Desktop 和 Devin CLI 上线。\n\n在 FrontierCode 2.0 上——这是我们用来基于质量和可合并性评估模型在真实工程任务中表现的基准——Gemini 4 Hydrogen 得分 38.2%，仅次于 GPT-6.1 Sol。","sourceName":"X：Cognition (@cognition)","firstParty":false,"publishedAt":"2026-11-12T18:44:28.000Z","url":"https://x.com/cognition/status/2120950876248641588"},{"id":"mt013742fhedisepp2i31h1r4","title":"Gemini 4 Hydrogen 上线 Cursor，CursorBench 得分 54.3%","summary":"作者以「爱好包括制作 og:images」调侃，配图为 CursorBench 4.0 的模型散点图；其引用 Cursor 官方内容称 Gemini 4 Hydrogen 现已在 Cursor 上线，默认 effort 下 CursorBench 得分 54.3%，高于 Gemini 3.8 Flash 的 39.6%。","sourceName":"X：Matt Palmer（SpaceXSI，Grok Bot） (@mattyp)","firstParty":false,"publishedAt":"2026-11-12T18:22:08.000Z","url":"https://x.com/mattyp/status/2120945253666762973"},{"id":"leysijsx8660t8pwgnnslip9g","title":"Cursor 公布 Gemini 4 Hydrogen 定价","summary":"Gemini 4 Hydrogen 定价为每百万输入 token 1.50 美元，每百万输出 token 7.50 美元。\n\n对比各档 effort 水平：https://cursor.com/evals?v=1","sourceName":"X：Cursor (@cursor_ai)","firstParty":false,"publishedAt":"2026-11-12T18:19:44.000Z","url":"https://x.com/cursor_ai/status/2120944651960291781"},{"id":"vwpr1h68drk55b95gmxib4f4q","title":"Gemini 4 Hydrogen 现已登陆 Cursor，CursorBench 得分 54.3%","summary":"Cursor 宣布 Gemini 4 Hydrogen 现已可用。其默认 effort 下在 CursorBench 得分 54.3%，高于 Gemini 3.8 Flash 的 39.6%。","sourceName":"X：Cursor (@cursor_ai)","firstParty":false,"publishedAt":"2026-11-12T18:19:41.000Z","url":"https://x.com/cursor_ai/status/2120944639633211619"},{"id":"q7eh6zetx4dgeec6vz7r00onv","title":"Gemini 4 Hydrogen 发布，已上线 Gemini App","summary":"Google Labs VP Josh Woodward 宣布发布 Gemini 4 Hydrogen，现已可在 Gemini App 中使用。原文称该模型速度快、更智能、是一次大幅提升，未给出具体性能数据或技术细节。","sourceName":"X：Josh Woodward (@joshwoodward, Google Labs VP)","firstParty":false,"publishedAt":"2026-11-12T18:10:15.000Z","url":"https://x.com/joshwoodward/status/2120942262054232392"},{"id":"e3o0ut2he1m7y82w20od4ed48","title":"Gemini 4 Hydrogen 任务速度提升 2.5 倍","summary":"仅作一项对比，Gemini 4 Hydrogen 完成任务的速度比 3.8 Flash 快 2.5 倍，同时智能程度高得多，编造内容还少了 5 倍。\n\n这是个好模型 ：)","sourceName":"X：Logan Kilpatrick (@OfficialLoganK)","firstParty":false,"publishedAt":"2026-11-12T18:09:12.000Z","url":"https://x.com/OfficialLoganK/status/2120941998014390392"},{"id":"w3iirjuk8jtt1lka51a28bwv2","title":"Gemini 4 Hydrogen 开始向所有人推送，覆盖 Gemini App、搜索与 Gemini API","summary":"Google 宣布 Gemini 4 Hydrogen 即日起开始推送。所有用户可在 Gemini App、Google Search 和 Google AI Studio 使用；AI Pro 和 Ultra 订阅者还可用于 Antigravity、Chrome 中的 Gemini 和 Google Sheets 中的 Gemini；开发者和企业可在 Google AI Studio、AndroidStudio 及各档 Gemini API 使用。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-12T18:09:10.000Z","url":"https://x.com/Google/status/2120941989948457042"},{"id":"t1zssrg26pwcowrqz6buo5qp9","title":"Google 发布 Gemini 4 Hydrogen：智能、速度与可靠性大幅提升","summary":"Google 发布 Gemini 4 Hydrogen，称其在默认 high thinking 下于 Artificial Analysis 智能指数上超过 Argon，xhigh 下更高，且同类任务完成更快。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-12T18:09:09.000Z","url":"https://x.com/Google/status/2120941986895319158"},{"id":"clge7zh429cqvd5tz2zsr908w","title":"Google 发布 Gemini 4 Hydrogen，主打日常编码与智能体工作","summary":"Google 发布 Gemini 4 Hydrogen，面向日常编码和智能体工作，强调速度与效率。该模型提供 4 个思考级别，可独立使用或与 Carbon 和 Argon 协同，比 3.8 Flash 快 2.5X，官方称在其同级中领先竞争模型。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-12T18:09:08.000Z","url":"https://x.com/Google/status/2120941982004523367"},{"id":"mlams5mulqbf16g7tini41vf3","title":"Google 介绍 Hydrogen 四档思考级别与 Antigravity Orchestrator 多模型协作","summary":"Google 介绍 Hydrogen 提供低、中、高和新增 xhigh 四个思考级别，按可预期的方式权衡智能、延迟和 token 用量。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-12T18:09:08.000Z","url":"https://x.com/Google/status/2120941984148041901"},{"id":"ajvxvhu8bh001pourbhhjl0ir","title":"Artificial Analysis 评测 Gemini 4 Hydrogen：智能指数 54，接近 Sonnet 5.5 且成本约其 32%","summary":"Artificial Analysis 评测 Google 新发布的 Gemini 4 Hydrogen：新增 xhigh 推理档在 Intelligence Index 得 54 分，比 Claude Sonnet 5.5 (max) 和 GPT-6.1 Sol (max) 低 1 分，每任务成本约为 Sonnet 的 32%，但约为 GPT-6.1 Sol 的 2.5 倍。","sourceName":"X：Artificial Analysis (@ArtificialAnlys)","firstParty":false,"publishedAt":"2026-11-12T18:07:16.000Z","url":"https://x.com/ArtificialAnlys/status/2120941511223185722"},{"id":"psfuehcy5xg07khe2ggyazuhq","title":"Google 发布 Gemini 4 Hydrogen，与 Carbon、Argon 一起开启 Gemini 4 时代","summary":"Google 发布 Gemini 4 Hydrogen，与 Carbon 和 Argon 一起完整开启 Gemini 4 时代。作者 Logan Kilpatrick 表示自己已每日使用该模型，Google 内部有数千人也在使用，并给出博客链接 https://blog.google/innovation-and-ai/models-and-research/gemini-models/introducing-gemini-4-hydrogen/。","sourceName":"X：Logan Kilpatrick (@OfficialLoganK)","firstParty":false,"publishedAt":"2026-11-12T18:06:55.000Z","url":"https://x.com/OfficialLoganK/status/2120941424028029030"},{"id":"ybgw60e8kl0ckmqzx8x4n18q6","title":"Gemini 4 Hydrogen 开始向全球所有用户推送","summary":"Google Gemini 宣布 Gemini 4 Hydrogen 今日开始向全球所有用户推送，覆盖桌面、移动端和网页。免费用户可通过自动模型选择在适合该提示词的场景下使用 Gemini 4 Hydrogen，详情见 https://goo.gle/4AxH40q。","sourceName":"X：Gemini (@GeminiApp)","firstParty":false,"publishedAt":"2026-11-12T18:06:49.000Z","url":"https://x.com/GeminiApp/status/2120941398971318410"},{"id":"jpbfn2g31iz5iovg126icbq7l","title":"Gemini Hydrogen 加速交互原型迭代","summary":"日常原型设计与迭代。\n\n在探索和测试想法时，Hydrogen 能用更少的提示词生成干净、可用的布局，让交互项目的快速原型设计与优化变得轻松。","sourceName":"X：Gemini (@GeminiApp)","firstParty":false,"publishedAt":"2026-11-12T18:05:54.000Z","url":"https://x.com/GeminiApp/status/2120941167584108776"},{"id":"rtug94ind3nuemcslhudu9ver","title":"Gemini 推出 Hydrogen 逐步拆解任务并调用应用完成待办","summary":"Google Gemini 官方宣布 Hydrogen 功能，将用户目标逐步拆解，从上传内容、Gmail、Google Drive 及 Airtable、Dropbox 等 Connected Apps 拉取相关上下文。在 Gemini 中开始任务时，它会更频繁调用合适的工具和技能，帮助更快完成待办清单。","sourceName":"X：Gemini (@GeminiApp)","firstParty":false,"publishedAt":"2026-11-12T18:05:31.000Z","url":"https://x.com/GeminiApp/status/2120941072050471156"},{"id":"rt584cexu9fp97te4mb91obzr","title":"Google 发布 Gemini 4 Hydrogen","summary":"Google 发布 Gemini 4 Hydrogen，定位能力强且快速，让 Gemini 4 覆盖更多用户。该模型向 Google AI Studio、Gemini API、Gemini for business、Gemini 应用、Google Search 全量开放，付费 Google AI Pro + Ultra 订阅者可在 Google Antigravity 中使用。","sourceName":"X：Logan Kilpatrick (@OfficialLoganK)","firstParty":false,"publishedAt":"2026-11-12T18:05:02.000Z","url":"https://x.com/OfficialLoganK/status/2120940951292268640"},{"id":"rl7315tdvcb3agm4jz3u99e36","title":"Gemini Hydrogen 写作研究助手","summary":"开箱即用的写作、研究和日常工作。\n\nHydrogen 严格遵循你的语气、格式和具体规则，因此邮件草稿、学习指南、改写内容和复杂文档第一次就能直接使用。当你比较产品或综合密集材料时，它能整理出清晰的表格和可视化拆解，同时不遗漏关键细节。","sourceName":"X：Gemini (@GeminiApp)","firstParty":false,"publishedAt":"2026-11-12T18:04:53.000Z","url":"https://x.com/GeminiApp/status/2120940914843795865"},{"id":"hd9c1p8riw1bpzs4yepq4h64d","title":"Hydrogen 用自然语言秒生成可交互代码","summary":"除了知识工作，Hydrogen 还将同样的速度和一次通过准确率带入实时编程，在数秒内把自然语言转化为可运行、可交互的代码。\n\n在 Geminisland 中可以看到它的实际表现——这是一个演示游戏，用户可以通过提示词，借助 Gemini API 上的 Hydrogen 实时在共享岛屿上构建新的 3D 体素结构。","sourceName":"X：Google AI (@GoogleAI)","firstParty":false,"publishedAt":"2026-11-12T18:03:59.000Z","url":"https://x.com/GoogleAI/status/2120940684924403798"},{"id":"yg1hh9kmy0cj86m7f96b93pqn","title":"Google 发布 Gemini 4 Hydrogen，面向消费者和开发者全面开放","summary":"Google AI 宣布 Gemini 4 Hydrogen 从即日起可用。消费者可在 Gemini App 和 Google Search 中向所有用户开放，Google Sheets 中的 Gemini 面向 Google AI Pro 和 Ultra 订阅者；开发者和企业可通过 Google AI Studio 和 Android Studio 中的 Gemini API 构建，Google Antigravity 及 Gemini for business 面向付费 Pro 和 Ultra 订阅者。","sourceName":"X：Google AI (@GoogleAI)","firstParty":false,"publishedAt":"2026-11-12T18:03:59.000Z","url":"https://x.com/GoogleAI/status/2120940686811750596"},{"id":"oyvn2ybcdov39n3frh8j060lg","title":"Google 发布 Gemini 4 Hydrogen，扩展 Gemini 4 模型系列","summary":"Google AI 宣布推出 Gemini 4 模型系列新成员 Gemini 4 Hydrogen，面向日常编码和智能体工作流，主打速度与效率。","sourceName":"X：Google AI (@GoogleAI)","firstParty":false,"publishedAt":"2026-11-12T18:03:58.000Z","url":"https://x.com/GoogleAI/status/2120940683233984862"},{"id":"xron978vcvj09ct0oz6iuvbrj","title":"Google 发布 Gemini 4 Hydrogen，主打日常快速帮助","summary":"Google 官方宣布 Gemini 4 Hydrogen 发布，面向所有人提供前沿智能和快速日常帮助。官方称它更能贴近用户指令行事、正确调用合适的工具，用更少的来回沟通获得可靠输出。","sourceName":"X：Gemini (@GeminiApp)","firstParty":false,"publishedAt":"2026-11-12T18:03:39.000Z","url":"https://x.com/GeminiApp/status/2120940601319260164"},{"id":"v26fsdyhbktgyuedmrx25p58y","title":"Google Gemini 开放推送，覆盖开发者、企业与普通用户渠道","summary":"Google DeepMind 宣布开始向各渠道推送：开发者可在 Google AI Studio、Android Studio 中用 Gemini API，付费 Google AI Pro 和 Ultra 订阅者可在 Google Antigravity 中使用；企业可通过 Gemini for business 和 Google Antigravity 部署；所有用户可在 Google Search 和 Gemini 应用模型下拉菜单中访问。详情见 https://goo.gle/4zDCs8N。","sourceName":"X：Google DeepMind (@GoogleDeepMind)","firstParty":false,"publishedAt":"2026-11-12T18:02:37.000Z","url":"https://x.com/GoogleDeepMind/status/2120940342505566438"},{"id":"ckdk8km29wmrflsa2fte7y832","title":"Google 发布 Gemini 4 Hydrogen，任务速度较 3.8 Flash 快 2.5 倍","summary":"Google 在 Carbon + Argon 之后发布 Gemini 4 Hydrogen，主打面向日常任务、编码和智能体工作流的速度与效率。相比 3.8 Flash 任务完成速度快 2.5 倍，并提供 4 档思考级别，用户只需为任务所需的推理深度等待和付费。模型今日起向 Google AI Studio 各档位、Gemini API、Gemini App、Search 以及 Google AI Pro 和 Ultra 订阅用户的 Google Antigravity 推出。","sourceName":"X：Sundar Pichai (@sundarpichai)","firstParty":false,"publishedAt":"2026-11-12T18:02:12.000Z","url":"https://x.com/sundarpichai/status/2120940236805169182"},{"id":"uy1ayrrlqx1snqsv4lub7whsa","title":"Google DeepMind 发布 Gemini 4 Hydrogen","summary":"Google DeepMind 发布 Gemini 4 Hydrogen，定位快速执行日常编码与智能体工作流，面向 Gemini API、AI Studio、Gemini 应用、Google Search 等全层级开放。","sourceName":"Google DeepMind：Blog（RSS）","firstParty":true,"publishedAt":"2026-11-12T18:00:50.000Z","url":"https://deepmind.google/blog/introducing-gemini-4-hydrogen/"},{"id":"v98atslrmng6mh1ez8840nx38","title":"Google Search 全面接入 Gemini 4 Hydrogen","summary":"Google 宣布 Gemini 4 Hydrogen 已向全球所有用户开放于 Google Search，称为 Search 迄今最大的模型升级。改进包括更细腻的意图理解与指令跟随、增强的 query fan-out 推理以覆盖更多相关子主题链接、更多图片、结构化回复和对比表等可视化响应，以及所有支持 AI Mode 语言下更细致的回答质量。","sourceName":"Google Blog：AI（RSS）","firstParty":true,"publishedAt":"2026-11-12T18:00:00.000Z","url":"https://blog.google/products-and-platforms/products/search/gemini-4-hydrogen-search-upgrade/"},{"id":"e1tuwzogxnhwavo3muu1ivhdy","title":"Gemini 4 Hydrogen (gemini-4-hydrogen) 正式可用并成为 Antigravity 智能体默认模型","summary":"Google 在 Gemini API 更新日志中宣布 Gemini 4 Hydrogen (gemini-4-hydrogen) 正式可用 (GA)，面向日常编码和智能体工作流提供速度与效率。","sourceName":"Gemini API：更新日志（网页）","firstParty":true,"publishedAt":"2026-11-12T00:00:00.000Z","url":"https://ai.google.dev/gemini-api/docs/changelog#11-12-2026"},{"id":"v2mkjqo2c16gezu1uhe9d253j","title":"Gemini 4 Hydrogen vs 3.8 Flash 语音智能体实测：工具失败时零虚报且响应更快","summary":"LiveKit 工程师用故意设置失败的酒店预订工具，实测 Gemini 4 Hydrogen 与 gemini-3.8-flash 在语音智能体中的表现。54 份测试转写中 Hydrogen 零虚假工具报告，3.8 Flash 出现 2 次；Hygen 高档位下每轮首句延迟中位数 4,004 ms，比 3.8 Flash 默认档位的 5,212 ms 快 1.2 秒。","sourceName":"LiveKit 产品与工程博客","firstParty":true,"publishedAt":"2026-11-12T00:00:00.000Z","url":"https://livekit.com/blog/gemini-4-hydrogen-first-impressions"},{"id":"d45gkw7az0yba8svolkwbyw8a","title":"Google 发布 Gemini 4 Hydrogen，主打快速执行与多模型协作","summary":"Google 发布 Gemini 4 Hydrogen，定位为面向日常编码与智能体工作流的快速执行模型，与主打深度推理的 Gemini 4 Carbon 和 Argon 互补，现已覆盖 AI Studio、Gemini API、Gemini 应用、Google Search 等全部层级。","sourceName":"Hacker News：AI 热帖","firstParty":false,"publishedAt":"2026-11-11T16:00:00.000Z","url":"https://blog.google/innovation-and-ai/models-and-research/gemini-models/introducing-gemini-4-hydrogen/"}]},"d6f453c1-9dce-4af5-8a9a-ff7b8642493c":{"publicId":"d6f453c1-9dce-4af5-8a9a-ff7b8642493c","title":"微软365故障波及Claude，Anthropic通报中断","status":"active","sourceCount":1,"reportCount":1,"firstReportAt":"2026-11-13T13:10:18.303Z","latestAt":"2026-11-13T13:10:18.303Z","latest":"微软 Microsoft 365 大范围故障波及 Claude，Anthropic 连发多条状态通报","digest":"微软 Microsoft 365 出现近年最严重的服务故障之一，Exchange Online、Outlook、SharePoint 及部分 Teams 中断近一天半，微软高管为此致歉。Anthropic 称 Claude 部分服务的中断源于 Microsoft 365 连接问题，并通过 Claude Status 页面陆续发布多条通报。\n\n目前公开的信息只说明 Anthropic 将故障归因于微软侧连接，Claude 受影响的具体范围和恢复时间未在通报中给出。","digestUpdatedAt":"2026-11-13T13:26:00.388Z","reports":[{"id":"h2nxkfqpvkcqzof1dlta9j5w0","title":"微软 Microsoft 365 大范围故障波及 Claude，Anthropic 连发多条状态通报","summary":"微软 Microsoft 365 出现近年最严重的服务故障之一，Exchange Online、Outlook、SharePoint 及部分 Teams 中断近一天半，微软高管为此致歉。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-13T13:10:18.303Z","url":"https://www.ithome.com/1/026/948.htm"}]},"e5b4067f-6f2e-4f04-8799-21e4fbd9b590":{"publicId":"e5b4067f-6f2e-4f04-8799-21e4fbd9b590","title":"OpenAI推出ChatGPT Wallet，智能体可代用户购物","status":"active","sourceCount":8,"reportCount":9,"firstReportAt":"2026-11-13T15:00:00.000Z","latestAt":"2026-11-13T18:55:21.000Z","latest":"OpenAI 推出 ChatGPT Wallet，让 AI Agent 代用户完成支付","digest":"OpenAI推出支付功能ChatGPT Wallet，让ChatGPT Work、Codex和dots中的智能体在用户批准下完成购买，并沿用用户现有银行卡的保护机制。该功能由OpenAI与美国运通、万事达卡和Visa合作开发，初期不向交易收取佣金。\n\n初期仅向限量美国年满18岁的ChatGPT Pro订阅用户开放，且需绑定美国发行的Visa、万事达卡或美国运通卡。TechCrunch报道称，用户可让名为dot的智能体帮助决定买什么，再由其代为完成结账。\n\nChatGPT官方账号称，智能体支付时不会接触用户的实际卡号信息，每笔购买都需通过安全检查；该功能即日起在美国向Pro订阅用户的dot推出。X用户Rohan Paul称，每次购买需生物识别批准，智能体以替代真实卡号的token支付，卡号对商户和智能体均不可见；他还称OpenAI计划日后允许用户设置消费限额和类别、完全委托购买。","digestUpdatedAt":"2026-11-13T19:11:05.661Z","reports":[{"id":"e2adsv8qtekpt20mxqjhmxe5r","title":"OpenAI 推出 ChatGPT Wallet，让 AI Agent 代用户完成支付","summary":"OpenAI 推出 ChatGPT Wallet，让 AI Agent 代用户支付，此前因灵活性不足放弃了 Instant Checkout。该功能目前仅在美国通过 Dots 上线，需要 ChatGPT Pro 订阅和符合条件的美国银行卡；商家和 Agent 都看不到真实卡号，由 American Express、Mastercard 和 Visa 生成支付令牌完成付款。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-13T18:55:21.000Z","url":"https://the-decoder.com/openai-rebuilt-ai-shopping-from-scratch-with-chatgpt-wallet/"},{"id":"gtri2wqpaqm88wga1fo3unzkh","title":"OpenAI dots 智能体可通过 ChatGPT Wallet 购物，每笔需生物识别批准","summary":"OpenAI 的 dots 智能体现在可通过 ChatGPT Wallet 代用户购物，每次购买需生物识别批准。用户保存一次借记卡或信用卡后，智能体用以替代真实卡号的 token 支付，卡号对商户和智能体均不可见，持卡人保留原有奖励和保护；系统由 American Express、Mastercard 和 Visa 与 OpenAI 共同构建。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-13T18:01:47.000Z","url":"https://x.com/rohanpaul_ai/status/2121302521851621689"},{"id":"jj768amkn6ylnwh878i92r5ya","title":"OpenAI 联合 American Express、Mastercard 和 Visa 推出 ChatGPT Wallet","summary":"OpenAI 推出 ChatGPT Wallet，与 American Express、Mastercard 和 Visa 合作，让 dot 可安全代用户完成购物。智能体支付时无法接触真实卡片信息，每次购买都需安全检查和用户批准；功能即日起向美国 Pro 订阅用户的 dot 推出。","sourceName":"X：Greg Brockman (@gdb)","firstParty":false,"publishedAt":"2026-11-13T17:32:45.000Z","url":"https://x.com/gdb/status/2121295213025194172"},{"id":"czp2y4hzb8bf1qhwlqzvw7a7g","title":"OpenAI 推出 ChatGPT Wallet，智能体可在用户批准下代为支付","summary":"OpenAI 推出 ChatGPT Wallet，智能体（dot）可在用户批准下安全地代为完成购买，无需接触用户实际银行卡信息，每笔购买都需通过安全校验。该功能即日起向美国 Pro 订阅用户的 dot 推出。Codex 产品设计员工 Ed Bayes 转发宣布，并表示团队同时上线了多项体验改进，详情见 https://openai.com/index/introducing-chatgpt-wallet/。","sourceName":"X：Ed Bayes（OpenAI，Codex 产品设计） (@edbayes)","firstParty":false,"publishedAt":"2026-11-13T16:54:28.000Z","url":"https://x.com/edbayes/status/2121285578876719586"},{"id":"sx5a9s0pgv35iwywziinladgi","title":"ChatGPT 携手三大卡组织打造钱包","summary":"我们正与 American Express、Mastercard 和 Visa 携手，联合企业与开发者，共同打造 ChatGPT Wallet，让智能体支付值得信赖、稳定可靠。","sourceName":"X：ChatGPT (@ChatGPT)","firstParty":false,"publishedAt":"2026-11-13T16:44:49.000Z","url":"https://x.com/ChatGPT/status/2121283153205883030"},{"id":"vot1htumxjgnb0i88rbq3zsuq","title":"ChatGPT 推出 ChatGPT Wallet，dot 可在用户批准下代为完成购买","summary":"ChatGPT 官方账号宣布推出 ChatGPT Wallet，dot 可在用户批准下安全地代用户完成购买。智能体支付时不会接触用户的实际卡号信息，每笔购买都需要通过安全检查。该功能即日起在美国向 Pro 订阅用户的 dot 推出，详情见 https://openai.com/index/introducing-chatgpt-wallet/。","sourceName":"X：ChatGPT (@ChatGPT)","firstParty":false,"publishedAt":"2026-11-13T16:44:49.000Z","url":"https://x.com/ChatGPT/status/2121283151729496235"},{"id":"qb9i34aoob3o14uusgqvgwa22","title":"OpenAI 推出 ChatGPT Wallet，AI 智能体可代用户购物并完成结账","summary":"OpenAI 于周五推出 ChatGPT Wallet，用户可让名为 dot 的智能体帮助决策购物并代为完成结账。功能初期向限量美国 18 岁以上 ChatGPT Pro 订阅者开放，需绑定美国发行的 Visa、Mastercard 或 American Express。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-13T16:00:12.000Z","url":"https://techcrunch.com/2026/11/13/chatgpts-new-wallet-lets-ai-agents-shop-and-check-out-for-you/"},{"id":"g220zd8m7x2dqoi9qs3fokla8","title":"OpenAI 推出支付功能 ChatGPT Wallet，让 dot 智能体代用户购物","summary":"OpenAI 于 11 月 13 日推出支付功能 ChatGPT Wallet，与美国运通、万事达卡和 Visa 合作开发，让旗下 dot AI 智能体代替用户购物。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-13T15:49:08.710Z","url":"https://www.ithome.com/1/026/994.htm"},{"id":"up9jrgyt5vkvf24zv3wl8yg9l","title":"OpenAI 推出 ChatGPT Wallet，让智能体在用户批准下完成支付","summary":"OpenAI 推出 ChatGPT Wallet，为 ChatGPT Work、Codex 和 dots 中的智能体提供一种安全的支付方式。购买需经用户批准，并沿用用户现有银行卡的保护机制。","sourceName":"OpenAI：官网动态（RSS · 排除企业/客户案例）","firstParty":true,"publishedAt":"2026-11-13T15:00:00.000Z","url":"https://openai.com/index/introducing-chatgpt-wallet"}]},"77f8b937-8e1a-4b05-b3eb-b609445fedd4":{"publicId":"77f8b937-8e1a-4b05-b3eb-b609445fedd4","title":"DeepSeek 开放 App 能力 API，扩展调用另收费","status":"active","sourceCount":5,"reportCount":9,"firstReportAt":"2026-11-12T16:00:00.000Z","latestAt":"2026-11-13T15:31:21.000Z","latest":"下一个超级 App 不必是面向所有人的一个超级 App。 现在，每个人都有能力创造一个超级 App。 下一个超级 App 也可以是只属于你一个人的超级 App。","digest":"DeepSeek 于 11 月 13 日将 App 对话背后的能力开放给开发者：在原有 API 中开启对应参数，即可使用联网搜索、文件输入、阅读链接等功能，工具调用与上下文拼接由服务端完成。V4.1-Flash 模型（deepseek-flash）已在 Messages、Responses 与 Chat Completions 接口下支持这些能力；语音及底层能力另设独立接口，含 OCR、ASR、TTS，可单独或组合调用。\n\nDeepSeek 称，调用扩展能力时除 Token 费用外，还将收取相关工具的调用费用，具体定价随公告另行列出。对外提供应用服务的开发者须开启内容安全参数，并自行承担内容安全审核、大模型登记、AI 标识等义务。\n\n官方同时提供可导入 DeepSeek 对话历史的开源前端演示（github.com/deepseek-ai/chat-demo）。投资人 Tianyi Cui 转发公告称，开发者可用少量参数启用内置功能，在自建应用中还原完整 App 体验。","digestUpdatedAt":"2026-11-13T15:36:56.725Z","reports":[{"id":"o2ud9vu2a6bmucuidc30u52zk","title":"下一个超级 App 不必是面向所有人的一个超级 App。 现在，每个人都有能力创造一个超级 App。 下一个超级 App 也可以是只属于你一个人的超级 App。","summary":"下一个超级 App 不必是面向所有人的一个超级 App。 现在，每个人都有能力创造一个超级 App。 下一个超级 App 也可以是只属于你一个人的超级 App。","sourceName":"X：Tianyi Cui（@tianyi）","firstParty":false,"publishedAt":"2026-11-13T15:31:21.000Z","url":"https://x.com/tianyi/status/2121264664571269160"},{"id":"jak4hoym9ycotkw4heqsfryp9","title":"DeepSeek 开放全家桶应用 API，开发者可 1:1 复刻 DeepSeek App","summary":"DeepSeek 于 11 月 13 日晚宣布正式开放全家桶应用 API，在原有 API 中开启对应参数即可获得深度思考搜索、文件输入等对话功能，语音及底层能力也开放独立接口。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-13T14:29:06.313Z","url":"https://www.ithome.com/1/026/960.htm"},{"id":"aqnmn2n2rzh2yjbniearntagd","title":"DeepSeek 将 App 核心能力通过 API 开放并附开源前端演示","summary":"作者转发 DeepSeek 官方公告：DeepSeek App 背后的搜索、文件、链接、安全和语音等能力现已通过 DeepSeek API 开放，可通过少量参数启用内置功能，或调用 OCR、ASR、TTS 等独立 API，在自建应用中还原完整 App 体验。官方同时提供支持导入 DeepSeek 对话历史的开源前端演示，代码见 https://github.com/deepseek-ai/chat-demo，详情见 https://api-docs.deepseek.com/guides/build_a_chatbot。作者期待功能实现门槛降低后社区能产出更多样的产品。","sourceName":"X：Tianyi Cui（@tianyi）","firstParty":false,"publishedAt":"2026-11-13T14:28:07.000Z","url":"https://x.com/tianyi/status/2121248749343420437"},{"id":"ywxxfyptevy24rytjj3n4q2td","title":"DeepSeek App 能力开放自由调用","summary":"🌱 更多可能性，等你来构建\n\nDeepSeek App 只是与 AI 交互的一种方式。它的能力现在可以由你自由调用与组合。少花时间重建基础功能，多花时间创造新事物。\n\n用 DeepSeek 构建。让想象力引领。\n\n4/4","sourceName":"X：DeepSeek (@deepseek_ai)","firstParty":false,"publishedAt":"2026-11-13T14:24:46.000Z","url":"https://x.com/deepseek_ai/status/2121247907076813077"},{"id":"t24t8354ribo501q0x9aymjo1","title":"DeepSeek API 工具调用计费说明","summary":"💰 API 定价\n\n扩展能力除标准 token 费用外，还会产生工具使用费用。\n工具定价明细见下文。\n\n3/4","sourceName":"X：DeepSeek (@deepseek_ai)","firstParty":false,"publishedAt":"2026-11-13T14:24:45.000Z","url":"https://x.com/deepseek_ai/status/2121247903603941471"},{"id":"c519wztfethigml59ijbepa9x","title":"DeepSeek 将 App 全套能力开放至 API，含搜索、文件与语音","summary":"DeepSeek 宣布 App 背后的能力现已通过 DeepSeek API 开放，涵盖搜索、文件、链接、安全与语音。开发者可用少量参数启用内置功能，或单独调用 OCR、ASR、TTS 等 API，并提供了支持导入 DeepSeek 对话历史的开源前端 Demo。","sourceName":"X：DeepSeek (@deepseek_ai)","firstParty":false,"publishedAt":"2026-11-13T14:24:44.000Z","url":"https://x.com/deepseek_ai/status/2121247896918253875"},{"id":"pccvkmzla239p7ysemtetxx4p","title":"DeepSeek V4.1-Flash 支持内置搜索、文件解析与安全检查等工具能力","summary":"DeepSeek 宣布 V4.1-Flash（deepseek-flash）在 Messages、Responses 和 Chat Completions 中支持内置工具，工具调用和上下文组装由服务端处理。","sourceName":"X：DeepSeek (@deepseek_ai)","firstParty":false,"publishedAt":"2026-11-13T14:24:44.000Z","url":"https://x.com/deepseek_ai/status/2121247899699036516"},{"id":"w1edyi7hrsgj7uk5j4amwwwff","title":"DeepSeek 开放全家桶应用 API，V4.1-Flash 支持联网搜索、文件输入与语音独立接口","summary":"DeepSeek 官方宣布开放全家桶应用 API，在原有 API 中开启对应参数即可获得深度思考搜索、文件输入、阅读链接、模型安全等对话能力，V4.1-Flash 模型（deepseek-flash）已在 Messages、Responses 与 Chat Completions 接口下支持这些功能。","sourceName":"公众号：DeepSeek（深度求索）","firstParty":false,"publishedAt":"2026-11-13T14:19:36.000Z","url":"https://mp.weixin.qq.com/s/78KBHc4-4N5b2vfL9SkutQ"},{"id":"nnbnoebf6mvo97usmwj5wziyl","title":"DeepSeek 开放全家桶应用 API：联网搜索、文件输入、阅读链接等能力面向开发者","summary":"DeepSeek 在 API 中开放此前 App 对话服务所用的能力，开发者开启对应参数即可使用，工具调用与上下文拼接由服务端完成。","sourceName":"DeepSeek：API 更新日志","firstParty":true,"publishedAt":"2026-11-12T16:00:00.000Z","url":"https://api-docs.deepseek.com/zh-cn/updates/#发布全家桶应用-api"}]},"dad94af2-7539-4652-a661-03cc5494c71b":{"publicId":"dad94af2-7539-4652-a661-03cc5494c71b","title":"Anthropic 向 Team 和 Enterprise 推出 Claude Meetings beta","status":"active","sourceCount":8,"reportCount":11,"firstReportAt":"2026-11-12T00:00:00.000Z","latestAt":"2026-11-12T22:36:29.000Z","latest":"Anthropic 发布 Claude Meetings，Claude 可加入团队视频会议协作","digest":"Anthropic 以 beta 形式向 Team 和 Enterprise 计划推出 Claude Meetings，可在 Claude 和 Claude Desktop 中使用。Claude 作为可见参与者加入 Google Meet 通话，团队成员可口头或在聊天中提问、让它起草文档，并实时看到和纠正它生成的内容；通话结束后，笔记、行动项、转录和 Claude 生成的内容都保存在 Claude 中该会议的页面上。\n\nAnthropic 称目前从 Google Meet 开始支持，其他视频会议平台的支持即将推出，但未公布时间。据 Rohan Paul 介绍，Claude 会对每个口头请求先确认发言者身份再执行；默认情况下，一旦有组织外部人员加入 Google Meet 通话，它就会退出。The Decoder 报道称，采用 HIPAA 或客户管理加密配置的组织暂时无法使用 Meetings。\n\n费用方面，Anthropic 称 beta 期间 Team 和 Enterprise 计划的笔记和转录免费，通话中的回答也免费，但回答若调用已连接的工具，则计入该计划用量；通话中生成的文档、白板等产物免费至 2027 年 2 月 10 日。该功能目前仅限上述两个计划，且处于 beta 阶段，尚未公布面向其他计划或正式版的时间。","digestUpdatedAt":"2026-11-12T22:49:22.048Z","reports":[{"id":"kikcmqsbwnwg3mb8xoh2h2dot","title":"Anthropic 发布 Claude Meetings，Claude 可加入团队视频会议协作","summary":"Anthropic 推出 Claude Meetings，可将 Claude 加入团队视频通话，在会议进行中与你共同生成文档、白板等 artifacts。该功能已在 Team 和 Enterprise 计划以 beta 形式开始逐步推送。","sourceName":"X：Ado Kukic（Anthropic 开发者关系，Claude Code） (@adocomplete)","firstParty":false,"publishedAt":"2026-11-12T22:36:29.000Z","url":"https://x.com/adocomplete/status/2121009263997010306"},{"id":"fyy46ximozmo3jopdn6viv7w4","title":"Anthropic 推出 Claude Meetings，可加入团队视频通话实时协作","summary":"Anthropic 推出 Claude Meetings：把 Claude 加入团队视频通话后，它能在你还在讲话时就与你一起构建文档、白板等产物。该功能正以 beta 形式开始向 Team 和 Enterprise 计划推出。","sourceName":"X：Noah Zweben（@noahzweben）","firstParty":false,"publishedAt":"2026-11-12T21:15:49.000Z","url":"https://x.com/noahzweben/status/2120988963137810578"},{"id":"fii8iaht4yklmdxiud8qy18od","title":"Anthropic 推出 Claude Meetings，让 Claude 以参会者身份加入视频会议","summary":"Anthropic 推出 Claude Meetings 功能，让 Claude 以可见参会者身份加入视频通话，可回答问题、生成文档和白板、记录笔记与行动项。会议结束后所有产出可在 claude.ai 专用页面查看。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-12T20:26:50.000Z","url":"https://the-decoder.com/claude-meetings-lets-anthropics-ai-join-your-video-calls/"},{"id":"eifuwvcjk4e3hk7iedz0ur7zj","title":"Anthropic 推出 Claude Meetings，可像参会者一样加入 Google Meet","summary":"Rohan Paul 介绍 Anthropic 新推出的 Claude Meetings（beta），可像参会者一样加入 Google Meet，在会中实时听取并完成通常会后才安排的工作。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-12T20:20:44.000Z","url":"https://x.com/rohanpaul_ai/status/2120975099960721597"},{"id":"ejdq68qv8qvj61bp0suii0270","title":"Claude Meetings 现支持 Google Meet，更多视频会议平台即将加入","summary":"Anthropic 官方宣布 Claude Meetings 从 Google Meet 开始支持，其他视频会议平台的支持即将推出。详情见 https://claude.com/resources/articles/claude-meetings。","sourceName":"X：Claude (@claudeai)","firstParty":false,"publishedAt":"2026-11-12T20:16:22.000Z","url":"https://x.com/claudeai/status/2120974000746582357"},{"id":"khunutyhfztjlbm52uzwlze4q","title":"Claude 加入会议成为可见参与者","summary":"Claude 作为可见参与者加入。你可以大声提问或在聊天中提问，也可以让它起草文档。你的团队能看到它正在构建的内容，并在成形过程中进行纠正。","sourceName":"X：Claude (@claudeai)","firstParty":false,"publishedAt":"2026-11-12T20:16:21.000Z","url":"https://x.com/claudeai/status/2120973996304830859"},{"id":"kq2om5zvywnzs9u87374sf9q6","title":"Claude 新增会议记录功能，会后自动整理笔记与行动项","summary":"Anthropic 的 Claude 宣布接管会议记录工作。通话结束后，笔记、行动项、转录内容以及 Claude 生成的一切产出都会保存在 Claude 中该会议的页面上。","sourceName":"X：Claude (@claudeai)","firstParty":false,"publishedAt":"2026-11-12T20:16:21.000Z","url":"https://x.com/claudeai/status/2120973999295643679"},{"id":"iifokh8bszrjeauww4d3ri073","title":"Anthropic 发布 Claude Meetings，可在视频会议中与团队协作生成文档和白板","summary":"Anthropic 推出 Claude Meetings，把 Claude 加入团队视频通话后，它能在对话进行中与你共同构建文档、白板等 artifacts。该功能正以 beta 形式在 Team 和 Enterprise 计划上逐步推出。","sourceName":"X：Claude (@claudeai)","firstParty":false,"publishedAt":"2026-11-12T20:16:20.000Z","url":"https://x.com/claudeai/status/2120973994191094179"},{"id":"flobw48sm2tlkfp190q774nqq","title":"Anthropic 推出 Claude Meetings，可在视频会议中实时协作并生成会议产物","summary":"Anthropic 推出 Claude Meetings，把 Claude 以可见参会者身份加入团队视频会议，在通话过程中实时创建文档、白板等产物，团队成员可边看边纠正，Claude 同时负责会议记录。","sourceName":"Claude：YouTube（RSS）","firstParty":true,"publishedAt":"2026-11-12T20:10:59.000Z","url":"https://www.youtube.com/watch?v=YUYeHMsqbmY"},{"id":"hyhofad7x4ang7yxog447pw08","title":"Claude Meetings 在 Team 和 Enterprise 计划开启 beta 测试","summary":"Claude Meetings 在 Claude 和 Claude Desktop 上向 Team 和 Enterprise 计划以 beta 形式推出。用户可将 Claude 作为可见参与者加入 Google Meet 通话，在通话中记笔记、回答问题，并构建 docs、白板和幻灯片等 artifacts。","sourceName":"Claude 应用发布说明","firstParty":true,"publishedAt":"2026-11-12T00:00:00.000Z","url":"https://support.claude.com/en/articles/12138966-release-notes#h_2d03630102"},{"id":"l36ne5q2gsdx6thyia7fi10kn","title":"Anthropic 推出 Claude Meetings，Claude 以参会者身份加入视频会议","summary":"Anthropic 推出 Claude Meetings beta，Claude 可作为可见参会者加入视频通话，在会中回答提问、协作创建文档和白板，并生成笔记和行动项。","sourceName":"Claude：Blog（网页）","firstParty":true,"publishedAt":"2026-11-12T00:00:00.000Z","url":"https://claude.com/blog/claude-meetings"}]},"82c796c0-3bf1-4c3a-8368-56913b4bf85d":{"publicId":"82c796c0-3bf1-4c3a-8368-56913b4bf85d","title":"Anthropic启动IPO路演，估值预期回落至1.25–1.75万亿美元","status":"active","sourceCount":21,"reportCount":80,"firstReportAt":"2026-10-25T16:00:00.000Z","latestAt":"2026-11-13T18:01:53.000Z","latest":"多家银行以美国出口管制为由，禁止中国大陆和香港投资者参与 Anthropic IPO","digest":"Anthropic 已启动 IPO 路演，拟发行 8.25 亿股 A 类普通股，其中公司发售约 8.01 亿股、现有股东出售约 2365 万股，公司不获后者所得；发行价区间为每股 70–78 美元，拟在纳斯达克以代码 ANT 上市。据路透社公布的招股说明书草案，公司计划通过 IPO 筹集最多 644 亿美元，并向谷歌、英伟达和 AMD 等基石投资者私募融资 260 亿美元，计入博通、美光、微软和台积电等出资后募资规模最高可达 904 亿美元。\n\n据《金融时报》援引投资者消息，公司拟募资 800–1000 亿美元，目标估值 1.25 万亿–1.75 万亿美元，CEO 阿莫迪已接受低于此前预期的估值；公司 9 月曾瞄准最高 2 万亿美元。据 WSJ，公司本周将设定估值区间，计划下周四或周五挂牌，部分机构投资者仍希望估值低于上周讨论的 1.5 万亿美元。\n\n估值下调发生在投资者质疑之后。据 Reuters 和 WSJ，投资者认为 1.5 万亿美元过高，有人提出仅 1 万亿美元，并怀疑原定下周启动的路演能否如期进行，还在等待更新文件未包含的 10 月营收数据。更新后的 S-1/A 首次披露第三季度业绩：经营利润从二季度盈利 9.74 亿美元转为亏损 5.67 亿美元，Q3 营收 170 亿美元，算力成本占营收比例从 48% 升至 58%；算力与基础设施合同承诺约 8954 亿美元，另有最高 1750 亿美元尚未定价。上市后，长期受益信托可任命七名董事中的四席，七位联合创始人合计掌握 50.1% 投票权。","digestUpdatedAt":"2026-11-13T18:09:54.158Z","reports":[{"id":"zqbqdxdjvxdhrl7z9zzwvi9qa","title":"多家银行以美国出口管制为由，禁止中国大陆和香港投资者参与 Anthropic IPO","summary":"据 Bloomberg 报道，多家银行拒绝中国大陆和香港投资者的认购订单，或认为其获配可能性很低，部分人士以美国出口管制规则 ITAR 为由。Anthropic 不予置评，此次 IPO 由 Goldman Sachs 和 Morgan Stanley 牵头，另有 20 家银行参与，股票预计 11 月 18 日定价后在 Nasdaq 以代码 ANT 交易。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-13T18:01:53.000Z","url":"https://the-decoder.com/banks-bar-chinese-and-hong-kong-investors-from-anthropic-ipo-over-us-export-controls/"},{"id":"ir04ccbh63mo2xavryooeewvr","title":"Anthropic IPO 获六倍超额认购，有望成史上最大规模 IPO","summary":"据 Bloomberg 报道，Anthropic 的 IPO 订单超出可售股份六倍，公司及其联合创始人拟通过公开发行募资至多 644 亿美元，另通过私募募资 260 亿美元，目标估值约 1.4 万亿美元，若达成将超过 SpaceX 的 IPO。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-13T15:15:08.000Z","url":"https://the-decoder.com/anthropics-ipo-is-six-times-oversubscribed-and-on-track-to-become-the-largest-public-offering-in-history/"},{"id":"k99zjo9hbtous9r6vmmz7pxyh","title":"Anthropic 官宣首次公开募股（IPO）","summary":"Anthropic 官方宣布启动首次公开募股（IPO），并公布入口 ipo.anthropic.com。Anthropic 已向 SEC 提交注册声明及招股说明书，证券在注册声明生效前不得出售，初步招股说明书可经高盛与摩根士丹利获取。","sourceName":"X：Anthropic (@AnthropicAI)","firstParty":false,"publishedAt":"2026-11-12T11:30:46.000Z","url":"https://x.com/AnthropicAI/status/2120841731302154708"},{"id":"xi0y19pbadxpvgcmzsm7c5byg","title":"Anthropic IPO 路演视频披露多芯片策略与算力乘数细节","summary":"Simon Willison 整理了 Anthropic IPO 路演视频的转录稿，称其中包含此前未公开的业务信息。","sourceName":"Simon Willison 博客","firstParty":false,"publishedAt":"2026-11-11T15:11:59.000Z","url":"https://simonwillison.net/2026/Nov/11/anthropic-ipo-roadshow/"},{"id":"r5kn7uexy6jx97qwxwvnpqrom","title":"Anthropic IPO 拟募资最高 90.4B 美元，或成史上最大上市","summary":"Bloomberg 报道 Anthropic IPO 已获数倍于发行份额的订单，主要来自大型机构投资者的锚定级意向。公司通过 IPO 加私募配售寻求最高 $90.4B，将超过 SpaceX 的 $85.7B 纪录成为史上最大上市，完全稀释估值目标约 $1.4T；Goldman Sachs 和 Morgan Stanley 牵头共 22 家银行，股票将以 ANT 在纳斯达克全球精选市场交易。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-11T14:38:51.000Z","url":"https://x.com/rohanpaul_ai/status/2120526677247939001"},{"id":"ajjv9abs8vd20j05emcig98ai","title":"WSJ：Anthropic 7 位创始人 IPO 各套现约 2.5 亿美元并保留控制权","summary":"WSJ 报道，Anthropic 7 位创始人将在 IPO 中各出售约 2.5 亿美元股票，每人保留约 180 亿美元持仓。据公司文件，每人出售近 3.4M 股，发行价区间预计 70 至 78 美元，上市预计下周进行，估值接近 1.3 万亿美元，募资 800 亿美元以上，部分通过包括 Google 在内的私募配售。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-11T05:47:04.000Z","url":"https://x.com/rohanpaul_ai/status/2120392847505715324"},{"id":"m7ul4psbkb5zyp0t254fr986o","title":"Anthropic 投资需求火热，承销商拟将 IPO 目标估值上调回 $1.5T 或更高","summary":"FT 报道，因投资者需求旺盛，Anthropic 承销商计划上调 IPO 定价，把目标估值拉回 $1.5T 或更高。周二文件设定 $70-$78 的发行区间，计入员工期权和受限股后对应 $1.26T-$1.41T 估值；若定价超出区间，募资将超过 $100B，其中 Google、Nvidia 和 Microsoft 将按 IPO 价格投资 $26B。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-11T00:58:06.000Z","url":"https://x.com/rohanpaul_ai/status/2120320127484969162"},{"id":"eo7ozgw5sry6i4d0al4cu43py","title":"Anthropic S-1 披露七位创始人 IPO 各套现约 2.5 亿美元","summary":"Anthropic 的 S-1 文件显示，七位联合创始人每人将出售 3,378,378 股，按 70 至 78 美元的发行价区间，每人套现约 2.36 亿至 2.64 亿美元。IPO 估值可能达到 1.4 万亿美元，七人通过 Class F 超级投票权股份合计控制 51.1% 的投票权。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-10T19:57:52.000Z","url":"https://techcrunch.com/2026/11/10/all-7-anthropic-founders-will-each-cash-out-about-250m-in-ipo/"},{"id":"j8x08g5wo30akk4mast68n79d","title":"Anthropic 再次修订 S-1：宣布已达责任扩展政策能力阈值，IPO 定价 $70-$78","summary":"Anthropic 再次修订 IPO 申请文件 S-1（Amendment No. 2），宣布已越过其 Responsible Scaling Policy 设定的阈值，即 AI 正大幅加快 AI 研究速度、需更强安全检查。这一判断基于其对未来模型的预期而非现有模型的表现，一周前的文件还只说\"可能即将\"越过。文件同时将 IPO 发行价定为每股 $70 至 $78。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-10T19:04:06.000Z","url":"https://x.com/rohanpaul_ai/status/2120231037569790385"},{"id":"go546q78uprsfowd1zsj1ig2d","title":"Anthropic 启动 IPO 路演：拟以每股 70 至 78 美元发行，估值最高约 1.4 万亿美元","summary":"据 Bloomberg 报道，Anthropic 启动 IPO 路演，拟发行最多 8.25 亿股 Class A 普通股，定价 70 至 78 美元，估值最高约 1.4 万亿美元，股票将以代码 ANT 在纳斯达克上市，最快下周四或周五开始交易。按区间上限募资约 644 亿美元，其中约 625 亿美元来自 Anthropic 自身的 8.01351 亿股新股，现有股东仅出售 2364.8646 万股，所得几乎全部归公司；此前传闻估值曾高达 2 万亿美元，下调发生在科技股抛售与选民对 AI 数据中心态度转冷的背景下。作者补充引用文件称，Anthropic 代码库 90% 以上的贡献由 Claude 编写。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-10T18:45:31.000Z","url":"https://x.com/rohanpaul_ai/status/2120226361864536385"},{"id":"qd2nhcf09xkrsuynw5ss7yzt7","title":"Anthropic 启动 IPO 路演，定价最高 78 美元、估值至多 1.4 万亿美元","summary":"Anthropic 启动 IPO 路演，拟以每股 70 至 78 美元发行最多 8.25 亿股 Class A 普通股，估值最高约 1.4 万亿美元，股票代码 ANT，最快下周四或周五在 Nasdaq 开始交易。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-10T18:40:01.000Z","url":"https://x.com/rohanpaul_ai/status/2120224979098939403"},{"id":"yshr81morbvxs39fq2y2rw6rg","title":"Gary Marcus 质疑 Anthropic 1.4 万亿美元 IPO 估值","summary":"Gary Marcus 评论 Anthropic 拟以最高 1.4 万亿美元估值 IPO，称该公司除一个异常季度外从未盈利，未来负债接近 9000 亿美元。他引用 Q2 环比增长 147% 而 Q3 降至 47% 的数据，认为 tokenmaxxing 退潮与中国竞品崛起使万亿估值失去依据，并援引 S-1 中公司自认成本将上升、收入增速难以为继的表述。","sourceName":"Gary Marcus：The Road to AI We Can Trust（RSS）","firstParty":false,"publishedAt":"2026-11-10T14:37:21.000Z","url":"https://garymarcus.substack.com/p/just-say-no-to-anthropics-ipo"},{"id":"vsl8mxe1wtsjxzuon4g65ap8b","title":"Anthropic IPO 定价每股 $70.00 至 $78.00，估值最高可达 $1.4 万亿","summary":"Anthropic 周二确认其 IPO 发行价预计在 $70.00 至 $78.00 每股之间，估值最高 $1.4 万亿，低于此前预期的最高 $2 万亿。据 The Wall Street Journal 报道，股票目标在下周四或周五开始交易，将申请在纳斯达克以代码 \"ANT\" 上市其 A 类普通股；作为对比，OpenAI 上周估值为 $1.25 万亿。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-10T14:06:54.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1030703/anthropic-ipo-1-4-trillion"},{"id":"bbqkapwzzux4qt6ns0zsh7b7s","title":"Anthropic 将 IPO 发行价区间定为 70 至 78 美元，隐含估值达 1.404 万亿美元","summary":"Anthropic 在更新后的 IPO 招股文件中将发行价区间定为每股 70 至 78 美元，共发行 8.25 亿股 A 类股，预计募资 577.5 亿至 643.5 亿美元，若按区间上限定价隐含估值可达 1.404 万亿美元，高于其 5 月融资时的 9650 亿美元估值。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-10T14:01:39.000Z","url":"https://techcrunch.com/2026/11/10/anthropic-sets-ipo-price-range-of-70-to-78-per-share-to-reach-an-implied-valuation-of-1-404-trillion/"},{"id":"m5rcmn2em2b1mrik078lupej8","title":"Anthropic 启动 IPO 路演：发行价 70 至 78 美元，目标估值超 1 万亿美元","summary":"Anthropic 启动 IPO 路演，公开发行 8.25 亿股 A 类普通股，定价每股 70 至 78 美元，目标估值最高 1.02 万亿美元，股票将在纳斯达克以代码 ANT 交易。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-10T12:13:03.000Z","url":"https://the-decoder.com/anthropic-kicks-off-ipo-roadshow-offering-shares-at-70-to-78-and-targeting-a-trillion-dollar-valuation/"},{"id":"hq4udij8d72th4omv72z1skgj","title":"Anthropic 拟通过 IPO 筹集最多 644 亿美元，另向谷歌、英伟达等私募融资 260 亿美元","summary":"据路透社公布的招股说明书草案，Anthropic 计划通过 IPO 筹集最多 644 亿美元，并向谷歌、英伟达和 AMD 等基石投资者私募融资 260 亿美元，计入博通、美光、微软和台积电等出资后募资规模最高可达 904 亿美元。IPO 初步定价区间为每股 70 至 78 美元，此前一日 Anthropic 曾撤回拟筹资 693 亿美元的备案文件并称定价细节不准确。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-10T11:40:20.710Z","url":"https://www.ithome.com/1/025/127.htm"},{"id":"d4f8o2c9r7r8b7fsdqnpev3eu","title":"据报道 Anthropic 推进 IPO，计划下周四或周五挂牌","summary":"据 The Wall Street Journal 报道，Anthropic 将在本周设定估值区间，计划下周四或周五开始交易。部分机构投资者正推动估值低于上周讨论的 1.5 万亿美元目标，该数字已低于几个月前传闻的 2 万亿美元。报道还提到其主要竞争对手 OpenAI 上周融资 110 亿美元后估值约为 1.25 万亿美元，低于其最初寻求的 200 亿美元融资规模。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-10T01:27:12.000Z","url":"https://techcrunch.com/2026/11/09/anthropic-reportedly-plans-to-move-forward-with-ipo-plans/"},{"id":"wrxlh5gesmj36fresoxbriak2","title":"Anthropic 启动 IPO 路演，拟发行 8.25 亿股 A 类普通股并申请以代码 ANT 上市纳斯达克","summary":"Anthropic 启动拟议 IPO 路演，拟发行 825,000,000 股 A 类普通股，其中 801,351,354 股由 Anthropic 发售、23,648,646 股由部分现有股东出售，Anthropic 不获后者出售所得款项。","sourceName":"Anthropic：Newsroom（网页）","firstParty":true,"publishedAt":"2026-11-09T16:00:00.000Z","url":"https://www.anthropic.com/news/roadshow-launch"},{"id":"n0tybsrqj4ylarv5v5ilu4pj5","title":"Bloomberg 报道 AI 融资遇冷，Anthropic IPO 估值讨论下探至 1.1 万亿美元","summary":"Bloomberg 报道，亚洲杠杆 AI 头寸遭遇追缴保证金，券商警告抛售可能延续，估值在交易完成前或进一步下跌。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-09T12:22:01.000Z","url":"https://x.com/rohanpaul_ai/status/2119767465253331109"},{"id":"cjulee90gasnt7mbhmxcuiiqj","title":"消息称 Anthropic 仍推进 IPO：拟募资 800 亿至 1000 亿美元，估值预期回落","summary":"据《金融时报》报道，Anthropic 仍在推进感恩节前的 IPO，预计募资 800 亿至 1000 亿美元，目标估值 1.25 万亿至 1.75 万亿美元，CEO 阿莫迪接受估值低于此前投资者预期的水平。科技股抛售和美国中期选举结果使上市难度上升，OpenAI 也已将私募估值从 1.4 万亿美元下调至 1.25 万亿美元。七位联合创始人已承诺将个人所持股权的 80% 捐给慈善事业。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-08T00:44:04.537Z","url":"https://www.ithome.com/1/023/854.htm"},{"id":"okhx4jjwucd647299qwzsl6ua","title":"Anthropic 拟感恩节前 IPO，接受低于预期的估值，募资 800–1000 亿美元","summary":"据《金融时报》援引投资者的消息，Anthropic 计划在感恩节前 IPO，拟募资 800–1000 亿美元，估值 1.25–1.75 万亿美元，低于最乐观投资者期望的 2 万亿美元，但高于当前 9650 亿美元。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-07T17:37:25.000Z","url":"https://the-decoder.com/anthropic-pushes-ahead-with-pre-thanksgiving-ipo-despite-tech-selloff-accepts-lower-valuation/"},{"id":"losfqwxesuanjnt62v032oo9o","title":"Anthropic IPO 估值存分歧，1.5 万亿美元仍被部分投资者嫌贵","summary":"据路透社报道，Anthropic 冲刺史上最大 IPO 时估值预期持续下调，原拟寻求高达 2 万亿美元估值，部分机构投资者认为 11 月上市时应在 1.5 万亿至 1.6 万亿美元之间，甚至有大型投资者认为更接近 1 万亿美元。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-07T01:36:48.637Z","url":"https://www.ithome.com/1/023/640.htm"},{"id":"kv9zqeiqr9wj29j6vmq9q6je6","title":"WSJ：投资者将 Anthropic IPO 估值预期从约 $2T 下调至 $1.5T","summary":"据 WSJ，投资者已将 Anthropic IPO 估值预期从约 $2T 下调至 $1.5T，部分人认为 $1T 更现实。民主党中期选举获胜后数据中心禁令担忧引发 $3.2T 美股抛售；Anthropic 10 月底 run rate 仍超 $80B，9 月 30 日持有 $146.6B 现金。OpenAI 在 $1.25T 估值下仅募得 $30B 目标中的 $11B，同样反映融资走弱。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-06T14:56:34.000Z","url":"https://x.com/rohanpaul_ai/status/2118719195072659833"},{"id":"ia9wi0z09zfes5ewdf4agb6nf","title":"Anthropic 1.5 万亿美元 IPO 因投资者质疑估值遇阻","summary":"据 Reuters，Anthropic 的 IPO 遇阻，投资者质疑 1.5 万亿美元估值过高，有投资者提出仅 1 万亿美元，公司 9 月曾瞄准最高 2 万亿美元估值。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-06T11:38:17.000Z","url":"https://the-decoder.com/anthropics-1-5-trillion-ipo-hits-resistance-as-investors-balk-at-valuation/"},{"id":"zzv4fx8jpa3068v4y2wxsw2ey","title":"Newcomer：OpenAI 与 Anthropic 融资路径分化，Anthropic IPO 仍在推进","summary":"Newcomer 作者采访参与两家融资的投资人后写道，Anthropic 正与 OpenAI 拉开距离，而 OpenAI 渴望翻身故事。有投资人称共同基金等长期投资者对 Anthropic 股份需求无限，预计 IPO 将在感恩节前完成；民主党中期选举大胜后政治环境更严峻，但 Anthropic 与民主党关系相对友好。","sourceName":"Newcomer 新闻长文（RSS）","firstParty":false,"publishedAt":"2026-11-04T21:15:13.000Z","url":"https://www.newcomer.co/p/latest-fundraising-efforts-show-openai"},{"id":"mr034xi1abyzx7gazv7l248lg","title":"Anthropic 明年 700 亿美元算力账单超全年收入，S-1 细节遭播客拆解","summary":"Saito 在听完 Prof G Markets 播客后撰文分析 Anthropic S-1 修订稿，指出其未来几年算力与数据中心总承诺达 8950 亿美元，其中未来 12 个月到期 700 亿美元，超过其 680 亿美元的年化收入（上季度收入 170 亿美元，同比涨 12 倍但环比增速从 144% 降至 47%）。","sourceName":"X：Saito 硬地骇客 (@SaitoWu)","firstParty":false,"publishedAt":"2026-11-04T09:37:20.000Z","url":"https://x.com/SaitoWu/status/2117914080371782063"},{"id":"zv5dl1agqwo6tkmhdamy17lt5","title":"Ed Zitron 解析 OpenAI 1.25 万亿美元估值融资与 Anthropic S-1/A 中的万亿级算力承诺","summary":"Ed Zitron 撰文认为 AI 行业资金正在枯竭。OpenAI 上周以 1.25 万亿美元估值融资 110 亿美元，低于此前计划的 300 亿美元、1.4 万亿美元估值；据 The Information，其 Q1 2026 成本收入与研发支出合计 121 亿美元，截至 3 月底持有逾 730 亿美元现金及有价证券。","sourceName":"Ed Zitron 长文 / Where’s Your Ed At（RSS）","firstParty":false,"publishedAt":"2026-11-03T17:16:20.000Z","url":"https://www.wheresyoured.at/running-dry/"},{"id":"byq9z2oinyhjrd8hrxql51wg5","title":"Anthropic S-1 新披露显示算力成本占比升至 58%，利润率承压","summary":"TechCrunch 分析 Anthropic 更新的 S-1 文件披露，Q3 营收达 170 亿美元、环比增长近 50%，但算力占营收比例从上一季的 48% 升至 58%，每美元算力对应营收从峰值约 2.08x 回落至 1.72x。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-03T17:07:01.000Z","url":"https://techcrunch.com/2026/11/03/anthropic-is-still-grappling-with-the-economics-of-compute/"},{"id":"fey67gtp70ulqn8j5il7kycxg","title":"Anthropic 在 S-1/A 招股文件中警示递归自我改进（RSI）临近","summary":"Anthropic 在周一更新的 S-1/A 招股补充文件风险提示中称，公司已利用 AI 开发新模型且部分能力跃升未被及时察觉，基于对下一代模型的内部预期，可能很快触及《负责任扩缩策略》定义的“由 AI 带来的爆发式技术进展”，即递归自我改进（RSI）标准。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-03T08:03:19.683Z","url":"https://www.ithome.com/1/021/626.htm"},{"id":"dertdpzq3sm7jhkbxyfqwxspp","title":"Anthropic 修订版 IPO 文件披露 8954 亿美元算力承诺，总额可达 1.07 万亿美元","summary":"Anthropic 在修订版 IPO 文件中披露 8954 亿美元算力承诺，另有最高 1750 亿美元合同尚未定价，总额约 1.07 万亿美元，约为其前九个月 332 亿美元收入的 32 倍。款项持续到 2045 年，一年内到期 698 亿美元，而公司现金及短期投资为 1319 亿美元；季度环比增速从 144% 放缓至 47%，收入达 170 亿美元，算力成本升至销售额的 58%。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-03T00:03:15.000Z","url":"https://x.com/rohanpaul_ai/status/2117407218849157258"},{"id":"h052dra38w9bfsy0ne6frvfpv","title":"GPU 租金半年翻倍，Tomasz Tunguz 解析 2027 年 AI 实验室的久期匹配难题","summary":"Tomasz Tunguz 基于 Anthropic S-1/A 数据分析称，GPU 短租价格从 $3 涨到 $12-13/小时，使 Anthropic 混合 GPU 等效小时成本从 $3.10 升至 $5.65。","sourceName":"Tomasz Tunguz 博客（VC 分析）","firstParty":false,"publishedAt":"2026-11-03T00:00:00.000Z","url":"https://tomtunguz.com/the-financial-engineering-essential-for-ai-in-2027/"},{"id":"p61czu93us1j0lli5em6rjkte","title":"WSJ：大投资者希望 Anthropic IPO 估值定在 1.5 万亿至 1.6 万亿美元","summary":"据 WSJ，大投资者希望 Anthropic 的 IPO 估值定在 1.5 万亿至 1.6 万美元区间，低于数月来讨论的近 2 万亿美元。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-02T23:40:43.000Z","url":"https://x.com/rohanpaul_ai/status/2117401551526600969"},{"id":"uj1dp8gyin78j1xfse943y5w0","title":"Anthropic 在 S-1A 中披露可能很快达到自身 RSI 定义","summary":"TechCrunch 报道，Anthropic 在周一修订的 S-1A 文件风险因素部分新增表述，称内部估计显示其可能很快达到负责任扩展政策中「AI 带来的显著加速进展」的定义，且过去曾未察觉 AI 研发带来的能力跃升，但目前没有任何现有模型被认定越过该阈值。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-02T22:14:50.000Z","url":"https://techcrunch.com/2026/11/02/anthropic-warns-that-its-very-close-to-rsi-capability-aka-self-building-ai/"},{"id":"xiu342i7osbgfxe2ezhrjndl0","title":"Anthropic 算力与基础设施合同承诺达 $895.4B，其中 $447.5B 须在 2031 年前支付","summary":"Anthropic 在更新的 IPO 文件中首次披露第三季度业绩，算力与基础设施合同承诺总额约 $895.4B，其中 $447.5B 须在 2031 年前支付，仅 $213.8B 可取消或附带条件。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-02T21:28:26.000Z","url":"https://x.com/rohanpaul_ai/status/2117368258571784296"},{"id":"p2ckhch6idwqa3tpmqqp2inb8","title":"Anthropic 更新的 S1/IPO 文件称未来模型可能临近递归自我改进阈值","summary":"Anthropic 更新的 S1/IPO 申报文件显示未来模型可能很快达到其递归自我改进（RSI）阈值，即 AI 能力以无重大 AI 帮助时最快持续速度的 2 倍提升，1 年相当于 2 年进展。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-02T18:43:26.000Z","url":"https://x.com/rohanpaul_ai/status/2117326734442049563"},{"id":"xvemmg9p83lxqktk7mc47zhcr","title":"Anthropic 更新 IPO 文件首次披露第三季度财报，从盈利 9.74 亿美元转为亏损 5.67 亿美元","summary":"Anthropic 更新 S-1 IPO 文件并首次披露第三季度业绩，经营利润从二季度盈利 9.74 亿美元转为三季度亏损 5.67 亿美元，主因是 50 亿美元的高价短期算力和 20 亿美元员工捐赠配比的非现金支出。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-02T16:01:15.000Z","url":"https://x.com/rohanpaul_ai/status/2117285920500273582"},{"id":"dpm21l66z2iizblehsdg09c8t","title":"美国白宫科技顾问萨克斯称 Anthropic 可能成为资本主义史上最伟大企业","summary":"美国白宫科学与技术顾问会议主席戴维·萨克斯在 All-In 播客分析 Anthropic 的 S-1 文件，称其很可能成为资本主义历史上最伟大企业，也可能是回报最高的风险投资项目。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-31T22:56:28.467Z","url":"https://www.ithome.com/1/020/633.htm"},{"id":"yqblvh40gus1ssc0rjvawh6fu","title":"Anthropic IPO 招股文件披露近 9000 亿美元隐性债务","summary":"Anthropic 近日提交 IPO 招股文件，彭博社报道其计划未来在服务器、建筑和电力等领域投入近 9,000 亿美元债务。该公司资产负债表显示 1,175 亿美元负债和 1,120 亿美元现金，而租赁合同及数据中心、电力和 GPU 采购协议等表外义务未直接体现；Anthropic 计划通过增加收入和筹集资金支付这些负债。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-31T03:25:09.697Z","url":"https://www.ithome.com/1/020/444.htm"},{"id":"vyd3tzicoe478uo8njsr8zt2v","title":"The Verge 解读 Anthropic S-1 文件中的奇迹叙事与风险披露","summary":"The Verge 分析 Anthropic 提交的 335 页 S-1 招股书，其中创始人信以带来奇迹时代为愿景，同时用 94 页风险因素警告模型可能对人类构成灾难性甚至生存风险。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-10-30T13:11:05.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1023070/anthropic-ipo-risk-factors-filing-miracles"},{"id":"ix29bodadp5bou498z79oflc2","title":"Anthropic S-1 披露：三分之二以上算力用于研发，服务客户仅占约四分之一","summary":"Rohan Paul 引用 Anthropic S-1 指出，至少三分之二的芯片开支用于模型训练、研发和 Claude 内部使用，而非服务客户。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-30T01:28:37.000Z","url":"https://x.com/rohanpaul_ai/status/2115979152100864127"},{"id":"wb6emxuh5ob2wh96egtwawgfu","title":"Anthropic S-1 文件解读：财务表现强劲但增长放缓存隐忧","summary":"作者通读 Anthropic 公开版 S-1 文件，认为公司财务状况好于预期：2026 年第二季度收入从一季度的 47 亿美元增至 116 亿美元，并录得首个运营利润，截至 6 月底现金储备仅次于 Google 和 Berkshire Hathaway。","sourceName":"Timothy B. Lee：Understanding AI（RSS）","firstParty":false,"publishedAt":"2026-10-29T19:10:41.000Z","url":"https://www.understandingai.org/p/anthropics-financials-are-surprisingly"},{"id":"o37r0y04qmlpx7m674ztwgsjr","title":"Anthropic 披露约 250 个客户年消费超 1000 万美元","summary":"Anthropic 在 Form S-1 注册文件中披露，截至 2026 年 9 月 30 日的 12 个月内，约 250 个客户对 Claude 的支出超过 1000 万美元。Fortune 10 全部企业每年支付至少 10 万美元，超过 50% 的 Fortune 500 和超过 30% 的 Global 2000 亦是如此；年付 10 万美元以上的客户贡献 2025 年收入的 76%，低于 2023 年的 90%。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-29T17:19:28.000Z","url":"https://x.com/rohanpaul_ai/status/2115856053015580896"},{"id":"r9bmkfh02wkycc8zmhw87h4q9","title":"SemiAnalysis 分析师解读 Anthropic S-1 招股书背后的 AI 经济账","summary":"The Verge Decoder 节目邀请 SemiAnalysis 分析师 Joey Brookhart 解读 Anthropic 提交的 S-1 招股书，公司拟在纳斯达克上市，估值区间 1.5 万亿至 2 万亿美元。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-10-29T14:00:00.000Z","url":"https://www.theverge.com/podcast/1021322/anthropic-ipo-filing-s-1-claude-semianalysis-joey-brookhart-interview"},{"id":"iuma7p8unle567lzy6hp5jpw9","title":"The Verge 解读 Anthropic S-1：约 8500 亿美元 compute 承诺押注递归自我改进","summary":"The Verge 作者分析 Anthropic S-1，认为其商业模式依赖高速增长：2026 上半年营收同比增长 14 倍至 $16.3 billion，净收入留存率 900%，但不可撤销采购承诺合计 $265.6 billion，加上未开始的租赁协议 $321.4 billion 及其他协议，未来 20 年承诺至少约 $850 billion。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-10-29T13:30:00.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1021476/anthropic-s-1-compute-recursive"},{"id":"x2h1bp5shee6v508nw7pjtvas","title":"Ed Zitron 长文解析 Anthropic S-1：称其把散户当作退出流动性","summary":"Ed Zitron 撰文批评 Anthropic 的 S-1 招股书，指其仅披露 Q2 盈利数据、省略 Q3 现金状况和付款明细，是在公司基本面变化前误导投资者。","sourceName":"Ed Zitron 长文 / Where’s Your Ed At（RSS）","firstParty":false,"publishedAt":"2026-10-28T17:51:00.000Z","url":"https://www.wheresyoured.at/exit-liquidity/"},{"id":"vidjbhx5bf45wdl488kst1wv8","title":"Anthropic IPO 文件披露现金及短期投资达 131.7B 美元，超过 Amazon 和 Microsoft","summary":"Anthropic 的 IPO 文件显示其现金及短期投资达 $131.7B，超过 Amazon 和 Microsoft，在美国非银行公司中仅次于 Berkshire Hathaway 和 Alphabet。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-28T17:11:27.000Z","url":"https://x.com/rohanpaul_ai/status/2115491649543635378"},{"id":"x1rs553t7mu2o69tdy90e54nc","title":"TechCrunch 解析 Anthropic IPO 治理结构：公众股东对董事会几乎没有话语权","summary":"TechCrunch 发文分析 Anthropic IPO 后的治理结构，公众股东对董事会人选几乎没有话语权。Long-Term Benefit Trust（成员包括 Ben Bernanke）持有 Class T 股，可选举和罢免 7 个董事席位中的多数；7 位联合创始人合计掌握 50.1% 股东投票权和 3 个董事会席位。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-28T15:27:21.000Z","url":"https://x.com/rohanpaul_ai/status/2115465450469601487"},{"id":"gxwqce1swocfo9bp3dgqy3dnj","title":"Anthropic S-1 显示 90% 增量毛利，SemiAnalysis 播客详解其中数字","summary":"Saito 转述 SemiAnalysis 播客对 Anthropic S-1 的解读：招股书口径为增量毛利 90%、推理毛利 85%、连续两个季度盈利，Q1 净收入留存达 500%，收入同比涨 1368% 而算力费用只涨 300%。","sourceName":"X：Saito 硬地骇客 (@SaitoWu)","firstParty":false,"publishedAt":"2026-10-28T09:32:56.000Z","url":"https://x.com/SaitoWu/status/2115376256929948006"},{"id":"c5zdgpchio31r2911elz4bbg6","title":"Anthropic 上市文件披露四类芯片混用布局，分析师称英伟达定价权或承压","summary":"据《商业内幕》10 月 28 日报道，Anthropic 在 S-1 上市申请文件中披露，公司把多家战略合作伙伴的算力整合成统一资源池，通过软件将计算任务分配到亚马逊 Trainium、谷歌 TPU、英伟达 GPU 和 AMD GPU 四类芯片上，以分散风险。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-28T06:35:47.357Z","url":"https://www.ithome.com/1/018/906.htm"},{"id":"q287d5f1xom92gova9cmmlq5g","title":"Anthropic IPO 文件将潜在市场规模估为每年 40 万亿美元","summary":"据 WSJ 报道，Anthropic 在 IPO 文件中将潜在市场规模估为每年 40 万亿美元，超过 SpaceX 此前 28.5 万亿美元的估算。其做法是把 2025 年全球知识工作者创造的经济价值（超过 40 万亿美元）整体视为自身市场，理由是前沿 AI 能提升这些工作者的生产力从而扩大该价值。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-28T02:05:34.000Z","url":"https://x.com/rohanpaul_ai/status/2115263675124838643"}]},"d7ab817c-174b-469d-8150-f55f492570e4":{"publicId":"d7ab817c-174b-469d-8150-f55f492570e4","title":"前OpenAI工程师称四家中国AI实验室用Blackwell训练模型","status":"active","sourceCount":3,"reportCount":3,"firstReportAt":"2026-11-13T00:42:32.000Z","latestAt":"2026-11-13T15:21:04.000Z","latest":"前 OpenAI 研究员称在六个中国 AI 模型中发现 Nvidia Blackwell 指纹","digest":"前 OpenAI 工程师 Will Depue 在 X 发帖称，他通过分析模型权重的初始化指纹，发现 DeepSeek、Moonshot、MiniMax 和蚂蚁集团的最新模型是在 NVIDIA Blackwell 芯片上训练的，而这类芯片被禁止出口到中国。他称权重初始化模式会随 GPU 类型和随机种子留下可追溯的指纹，并已公开 GitHub 验证代码。\n\nThe Decoder 的跟进报道称，Depue 点名的是四家实验室在 2026 年 4 月后发布的六个模型。该报道同时指出，这一方法严格来说只能说明权重由哪种硬件初始化，训练很可能在同一批系统上运行；报道还称，Depue 的报告表示其技术证据显示这些实验室能接触到 NVIDIA 顶级硬件，但本身不能证明存在芯片走私或违反美国出口法。上述结论目前来自 Depue 本人的说法，尚未见独立核实。","digestUpdatedAt":"2026-11-13T16:09:51.314Z","reports":[{"id":"q92ir58jcjtp3g9fn11jlb6ei","title":"研究称中国最强 AI 模型由被禁运的 Nvidia Blackwell 芯片训练","summary":"TechCrunch 报道，前 OpenAI 研究员 Will DePue 分析 DeepSeek、月之暗面、MiniMax 和蚂蚁集团开源模型权重后，称 Kimi K3 与 DeepSeek V4 等模型留有 Blackwell 芯片训练痕迹，而这些芯片被禁止出口到中国。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-13T18:40:30.000Z","url":"https://techcrunch.com/2026/11/13/export-banned-nvidia-chips-are-behind-chinas-most-powerful-ai-models-uh-oh-jensen/"},{"id":"j3qgd6oovxg49wu9drcrbcwkj","title":"前 OpenAI 研究员称在六个中国 AI 模型中发现 Nvidia Blackwell 指纹","summary":"前 OpenAI 研究员 Will DePue 发布取证分析，称 DeepSeek、月之暗面、MiniMax 和蚂蚁集团的六个 2026 年 4 月后发布的模型带有 Nvidia Blackwell 芯片的初始化权重指纹。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-13T15:21:04.000Z","url":"https://the-decoder.com/former-openai-researcher-says-he-found-nvidia-blackwell-fingerprints-hidden-inside-six-chinese-ai-models/"},{"id":"p9g8alrjslao3dn6von37647l","title":"前 OpenAI 工程师称通过权重初始化指纹分析发现 DeepSeek、Moonshot、MiniMax、蚂蚁集团使用 NVIDIA Blackwell 芯片训练模型","summary":"前 OpenAI 工程师 @willdepue 发帖称，模型权重初始化模式会随 GPU 类型和随机种子保留指纹，经搜索逾六万亿组合并用 B300、GB200 真机复现验证。","sourceName":"X：indigo (@indigox)","firstParty":false,"publishedAt":"2026-11-13T00:42:32.000Z","url":"https://x.com/indigox/status/2121040986256109987"}]},"8febc4b1-e8fa-4418-97c6-eb03dfa73f42":{"publicId":"8febc4b1-e8fa-4418-97c6-eb03dfa73f42","title":"Google发布Gemini Decision 1决策模型与Decisions API","status":"active","sourceCount":14,"reportCount":20,"firstReportAt":"2026-11-11T00:00:00.000Z","latestAt":"2026-11-13T01:10:07.000Z","latest":"Pipecat 1.16 新增 PerceptionReader，配合 Google Decision 1 识别语音语气与讽刺","digest":"Google 发布 Gemini Decision 1 模型及配套 Decisions API，不再逐 token 生成文本，而是对文本、图像、音频、视频和 PDF 输入一次性回答是非题、选择题和 rubric 评分，单次最多 1,000 个问题、256K 上下文，端到端延迟 150–250 毫秒，每个答案附置信度分数。该 API 已在 Google AI Studio 上线，输入定价 $0.10/百万 token、输出不收费，并提供免费额度供原型开发；Google 称其在共享基准套件上比使用 Interactions API 的 Gemini 3.5 Flash-Lite 成本效率高近 5 倍。\n\n第三方评测给出不同图景：Artificial Analysis 称 Gemini Decision 1 在 Decision Index v2.1 得 66 分，与 Elephant 9B、Jev 1.14 相当，落后并列领先的 Drex Max v1.1 和 GLiDE v1.2 各 7 分。Google 自己展示的演示则称其 4.5 秒扫描 100 张配送照片、每张回答 16 个问题，速度接近 Gemini 3.5 Flash-Lite 的 4 倍。\n\n该模型发布首日即上线 OpenRouter，Google Cloud 上的支持标注为即将推出；开发者使用 Gemini Developer API（v1beta）需 google-genai SDK 3.2 或更高版本。Pipecat 团队称已在 Pipecat 1.16 新增的 PerceptionReader 中测试该模型，流式输入音频可获得较准确的语气与讽刺判断。","digestUpdatedAt":"2026-11-13T01:40:10.598Z","reports":[{"id":"ablgaq8p9xqmr5dz7w3c3rabq","title":"Pipecat 1.16 新增 PerceptionReader，配合 Google Decision 1 识别语音语气与讽刺","summary":"Philipp Schmid 转发 Pipecat 团队动态：Pipecat 1.16 新增 PerceptionReader，用于捕捉用户说话的韵律、语气和讽刺等表达方式，作者认为此前语音智能体大多缺失这一维度。团队已在昨日发布的 Google Decision 1 上测试，向其流式输入音频可获得较准确的语气判断，demo 地址为 https://pipecat-google-decision-demo.vercel.app/ ，文档见 https://docs.pipecat.ai/api-reference/server/expressive/overview#perceptionreader-3 ，团队称正在探索多种表达力衡量方式。","sourceName":"X：Philipp Schmid（Google DeepMind 开发者体验） (@_philschmid)","firstParty":false,"publishedAt":"2026-11-13T01:10:07.000Z","url":"https://x.com/_philschmid/status/2121047925753258247"},{"id":"shb2cxiblvq7iuzx5ug97p4vi","title":"Latent Space AINews：Google 发布 Gemini Decision 1 决策模型，Claude Fable 5.2 登顶 Agent Arena","summary":"Latent Space 发布 AI 要闻汇总，核心是 Google 抢先 Anthropic 推出生产级校准多模态决策模型 Gemini Decision 1，单次前向完成封闭集决策，支持每请求最多 1000 个问题、256K 上下文，输入 $0.10/1M tokens 且输出免费，端到端延迟约 150–250ms。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-11-12T05:26:54.000Z","url":"https://latent.space/p/ainews-d-day-decision-models-day/"},{"id":"augt3chxot6cst3txu3h6snl1","title":"谷歌推出 Gemini Decisions API，基于 Gemini Decision 1 模型实现快速多模态决策","summary":"谷歌宣布推出 Gemini Decisions API，由全新 Gemini Decision 1 模型驱动，可在一次快速处理中对文本、图像、视频和 PDF 内容进行至多 1000 项是非判断、选项选择和标准评估。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-12T00:55:39.970Z","url":"https://www.ithome.com/1/025/858.htm"},{"id":"cwu3md9iafkda12s81kwsz9t7","title":"Google 发布 Gemini Decision 1 决策模型 API，Simon Willison 实测对比","summary":"Google 发布 Gemini Decision 1 决策模型 API，与 Jev 和 OpenAI 同属决策模型类别，支持 yes/no、选择和 rubric 打分三类问题，沿用 Jev 的术语 Noul 表示 yes/no 问题。","sourceName":"Simon Willison 博客","firstParty":false,"publishedAt":"2026-11-11T22:03:25.000Z","url":"https://simonwillison.net/2026/Nov/11/gemini-decisions-api/"},{"id":"i529ddohm7bqm204xi2fdv7p6","title":"Google 发布 Gemini Decisions API 与 Gemini Decision 1，输入定价 $0.10/M tokens","summary":"Google 发布 Gemini Decisions API，由新模型 Gemini Decision 1 驱动，单次请求可对最多 1000 个问题打分并返回校准概率，输出 token 计费为 0，输入定价 $0.10/M tokens，上下文 262,144 tokens，端到端延迟 150-250 ms。","sourceName":"MarkTechPost（RSS）","firstParty":false,"publishedAt":"2026-11-11T21:21:42.000Z","url":"https://www.marktechpost.com/2026/11/11/google-gemini-decisions-api-gemini-decision-1/"},{"id":"e055uwm3p70cmgp80bpk1wn79","title":"Google 发布 Gemini Decision 1 决策模型，Gemini API 每百万输入 token 仅 $0.10","summary":"Google 在 Gemini API 推出新决策模型 Gemini Decision 1，价格 $0.10 per 1M input tokens 且无额外费用，原生支持图像、音频、视频和 PDF，256K 上下文窗口，可回答 1K questions，可在 API 免费试用。Google Labs VP Josh Woodward 转发并表示团队经常用它构建应用，称其让应用更快更智能；附图基准对比显示其在 JeeBench 92.2%、MMAU 71.8% 等项领先对比模型。","sourceName":"X：Josh Woodward (@joshwoodward, Google Labs VP)","firstParty":false,"publishedAt":"2026-11-11T21:01:30.000Z","url":"https://x.com/joshwoodward/status/2120622974277734716"},{"id":"tc20zb2magcy73drkedizwofu","title":"Google DeepMind 发布 Gemini Decision 1，单次可处理 1,000 个封闭式问题","summary":"Google DeepMind 推出 Gemini Decisions API，底层模型 Gemini Decision 1 面向是非题、选择题和量表评分等封闭式决策，单次可处理最多 1,000 个独立问题，支持文本、图像、音频、视频和 PDF，150 到 250 毫秒内返回概率与置信度。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-11T20:12:46.000Z","url":"https://the-decoder.com/google-joins-the-decision-model-wave-with-gemini-decision-1-scoring-1000-questions-in-a-single-pass/"},{"id":"ac59bdk8ftgxgvflbfwfsshpe","title":"Gemini Decision 1 用清单式提问做照片决策","summary":"Gemini Decision 1 把照片判断改成回答 yes/no、多选和评分清单，而非让模型自由描述图片。演示中它 4.5 秒扫描 100 张配送照片，每张同时回答 16 个问题，速度接近 Gemini 3.5 Flash-Lite 的 4 倍，并据评分将异常件路由到理赔审核。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-11T18:26:32.000Z","url":"https://x.com/Google/status/2120583972505760016"},{"id":"ai5qd8q6pvshexpvj80op6hzm","title":"Google 推出 Decisions API 快速决策","summary":"大多数模型是为生成文本、创意内容或逐步推理而构建的。但并非每项任务都需要书面答案。\n\n当工作流或智能体只需要快速做出判断时，Decisions API 会返回经过校准的置信度分数（端到端 150–250 毫秒），价格为每 100 万输入 token 0.10 美元，在共享基准测试套件上，其成本效率比使用 Interactions API 的 Gemini 3.5 Flash-Lite 高出近 5 倍。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-11T18:26:31.000Z","url":"https://x.com/Google/status/2120583968676577709"},{"id":"mj3riahx31kxc8bg1qk1mx3lh","title":"Google 发布 Gemini Decision 1 模型及 Gemini Decisions API","summary":"Google 在 Google AI Studio 推出 Gemini Decisions API，由新模型 Gemini Decision 1 驱动。该模型不再逐 token 生成文本，而是将文本、图像、音频、视频和 PDF 输入与最多 1,000 个问题对照，单次通过即给出决策，不按输出 token 计费。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-11T18:26:30.000Z","url":"https://x.com/Google/status/2120583966272983331"},{"id":"hh33gzk6lm10h6i2kt66g9lbx","title":"Google 首个决策模型 Gemini Decision 1 上线 OpenRouter","summary":"Google 首个决策模型 Gemini Decision 1 上线 OpenRouter，发布首日即可调用。该模型可接收文本、图像、音频、视频或 PDF 加类型化问题，以概率形式回答是/否问题、从最多 255 个选项中选择或打分，上下文 262K，定价 $0.10/M input、output 免费。","sourceName":"X：OpenRouter (@OpenRouter)","firstParty":false,"publishedAt":"2026-11-11T18:23:00.000Z","url":"https://x.com/OpenRouter/status/2120583084005605816"},{"id":"wlkx8ntz14q1azrcsx0u3npmj","title":"Artificial Analysis 评测 Google 首个决策模型 Gemini Decision 1，Decision Index 得 66 分","summary":"Artificial Analysis 评测 Google DeepMind 发布的首个决策模型 Gemini Decision 1，在 Artificial Analysis Decision Index v2.1 得 66 分。","sourceName":"X：Artificial Analysis (@ArtificialAnlys)","firstParty":false,"publishedAt":"2026-11-11T18:18:53.000Z","url":"https://x.com/ArtificialAnlys/status/2120582049522127205"},{"id":"wksvftoklhf028l767f8xucrj","title":"Google AI Studio 决策 API 文档","summary":"查看 API 文档，了解更多入门信息！https://aistudio.google.com/docs/decisions-api","sourceName":"X：Logan Kilpatrick (@OfficialLoganK)","firstParty":false,"publishedAt":"2026-11-11T18:16:51.000Z","url":"https://x.com/OfficialLoganK/status/2120581534600343641"},{"id":"n79t0spfz7zgwe7qcvxvwaauv","title":"Google 在 Gemini API 推出 Gemini Decision 1 决策模型","summary":"Google 推出 Gemini Decision 1，定位为 frontier decision 模型，已在 Gemini API 开放。定价为每 100 万输入 token $0.10 且无额外费用，原生支持图像、音频、视频和 PDF，提供 256K 上下文窗口与 1K questions，可在 API 中免费试用。","sourceName":"X：Logan Kilpatrick (@OfficialLoganK)","firstParty":false,"publishedAt":"2026-11-11T18:16:26.000Z","url":"https://x.com/OfficialLoganK/status/2120581433639198885"},{"id":"k1o7m8sfd4polrbxmonxud4vd","title":"Google DeepMind 发布 Gemini Decision 1 模型与 Decisions API","summary":"Philipp Schmid 宣布 Gemini Decision 在 Google DeepMind 内部原型孵化 6 周后，正式随新 API 一起发布 Gemini Decision 1 模型。作者本人参与了 API 与模型的设计、构建和评估，并提供文档、博客和 Playground 入口供试用。","sourceName":"X：Philipp Schmid（Google DeepMind 开发者体验） (@_philschmid)","firstParty":false,"publishedAt":"2026-11-11T18:15:43.000Z","url":"https://x.com/_philschmid/status/2120581250582995318"},{"id":"yhy98p14wmm973u361pelzt3e","title":"Google DeepMind 发布 Gemini Decisions API 及 Gemini Decision 1 模型","summary":"Google DeepMind 的 Philipp Schmid 发布 Gemini Decisions API，用于回答是非题、选择题和 rubric 问题，由新模型 Gemini Decision 1 驱动。该 API 支持文本、图像、音频、视频和 PDF 输入，单次请求最多 1,000 个问题，256k 上下文，端到端延迟 150-250 ms，输入价格 $0.10 per 1M tokens、输出免费，每个答案附带置信度分数。","sourceName":"X：Philipp Schmid（Google DeepMind 开发者体验） (@_philschmid)","firstParty":false,"publishedAt":"2026-11-11T18:15:42.000Z","url":"https://x.com/_philschmid/status/2120581248859201675"},{"id":"a0qorvsg9mk2771bmeq28zxbz","title":"Gemini 决策 API 上线","summary":"在此了解更多 https://blog.google/innovation-and-ai/technology/developers-tools/gemini-decisions-api","sourceName":"X：Sundar Pichai (@sundarpichai)","firstParty":false,"publishedAt":"2026-11-11T18:15:20.000Z","url":"https://x.com/sundarpichai/status/2120581156882285031"},{"id":"rlhz0uwxo2p8xhc7vnbaoko7i","title":"Google 发布 Gemini Decisions API 与 Gemini Decision 1 决策模型","summary":"Sundar Pichai 宣布在 Google AI Studio 推出 Gemini Decisions API，由新模型 Gemini Decision 1 驱动，面向封闭集选择而非逐 token 生成文本。","sourceName":"X：Sundar Pichai (@sundarpichai)","firstParty":false,"publishedAt":"2026-11-11T18:15:20.000Z","url":"https://x.com/sundarpichai/status/2120581155078729728"},{"id":"r8hsm3m3munjwk1n3u885zszw","title":"Google 发布 Gemini Decisions API 与 Gemini Decision 1 模型，专注快速多模态封闭式决策","summary":"Google 推出 Gemini Decisions API，由新模型 Gemini Decision 1 驱动，可在 150-250ms 端到端延迟内对文本、图像、音频、视频和 PDF（最多 256K tokens）一次性评估最多 1000 个是/否、多选和评分题。","sourceName":"Google Blog：AI（RSS）","firstParty":true,"publishedAt":"2026-11-11T18:00:00.000Z","url":"https://blog.google/innovation-and-ai/technology/developers-tools/gemini-decisions-api/"},{"id":"xyi59vw1zcxyc6o44nlsy2eey","title":"Google 发布 Gemini Decision 1 模型及 Decisions API","summary":"Google 在 Gemini API 更新日志中发布 Gemini Decision 1（gemini-decision-1）和 Decisions API，用于对文本、图像、音频、视频和 PDF 做快速、校准的二元、分类和 rubric 决策，输出零 token。官方同步提供了定价、速率限制和 Decisions API 入门指南。","sourceName":"Gemini API：更新日志（网页）","firstParty":true,"publishedAt":"2026-11-11T00:00:00.000Z","url":"https://ai.google.dev/gemini-api/docs/changelog#11-11-2026"}]},"ee2e9a50-8def-4105-994e-06f5d0926408":{"publicId":"ee2e9a50-8def-4105-994e-06f5d0926408","title":"李彦宏在百度世界2026提出“智能组织”","status":"active","sourceCount":4,"reportCount":19,"firstReportAt":"2026-10-12T05:04:24.100Z","latestAt":"2026-11-12T07:01:37.000Z","latest":"百度推出 Token Exchange（词元所）大模型交易平台","digest":"百度创始人李彦宏在 11 月 12 日百度世界 2026 演讲中称，人工智能的下一幕是“智能组织”，即不同于通行科层制的 AI 原生组织体系，组织智能将成为企业最深的护城河。他称过去十年已形成芯片、云、模型、智能体四层技术栈，但要把技术进步转化为生产力，企业需超越传统层级制、采用 AI 原生运营方式，不能只把 AI 当个人提效工具，而要让数字员工进入销售、客服、研发、运营等环节。\n\n他提出三条组织进化原则：打破岗位边界、沉淀隐性知识、设计流程闭环，并预计岗位将收敛为“构建者”和“销售者”两类。\n\n同场李彦宏还发布大模型交易平台“词元所”，定位中立、可信，对模型做准入测试并持续监测，防止偷换模型、虚标参数，并按服务质量、兑现度、安全合规、商业履约等维度给提供方打分、形成公开信用档案；百度称上线一个月供应资源数已超 100 个，日均调用 Token 数突破 7000 亿。","digestUpdatedAt":"2026-11-13T08:42:57.974Z","reports":[{"id":"rci8nqvigv937bmg5991wm49u","title":"百度沈抖：智能组织需要智能云","summary":"百度集团执行副总裁、百度智能云事业群总裁沈抖在百度世界2026大会演讲中提出，智能组织需要智能云，智能云服务的是具体任务而非企业IT系统。百度智能云围绕“组织进化三原则”重新组织产品和服务，支持企业建设通用、专业与定制三类智能体。会上还发布百度天池1024卡超节点，单套可支撑5万亿参数模型训练，将于明年推向市场。","sourceName":"公众号：百度智能云（文心）","firstParty":false,"publishedAt":"2026-11-13T08:39:12.000Z","url":"https://mp.weixin.qq.com/s/l5DV65vnD_MpBEPhCF6zeQ"},{"id":"ilukbwerg0ikmbp8t1v7t8y0c","title":"百度昆仑芯M100投用，M300与天池超节点提前至2027年","summary":"百度在Baidu World 2026上把高端AI芯片进度提前整整一年，昆仑芯M100已投入实际使用，M300与1024卡天池超节点提前至2027年。新专用硬件将多轮AI响应延迟降低90%，系统吞吐量提升7倍。CEO李彦宏称具身智能目前大致相当于2016年的自动驾驶水平，距离大规模普及还需多年攻坚。","sourceName":"X：X.PIN (@thexpin)","firstParty":false,"publishedAt":"2026-11-12T10:51:53.000Z","url":"https://x.com/thexpin/status/2120831943172399403"},{"id":"irlg034u15fhw7doe8n1jroc8","title":"李彦宏：人工智能的下一幕是智能组织，将迎来三大机会","summary":"李彦宏在百度世界2026提出“人工智能的下一幕是智能组织”，并首次提出打破岗位边界、沉淀隐性知识、设计流程闭环的“组织进化三原则”。百度同时正式推出大模型交易平台词元所，定位为大模型的交易所。他还判断推理将成为AI芯片长期持续增长的主要推动力，智能组织将带来轻资产运营、构建新护城河、创造和发现新市场三大机会。","sourceName":"公众号：百度智能云（文心）","firstParty":false,"publishedAt":"2026-11-12T10:04:05.000Z","url":"https://mp.weixin.qq.com/s/NXxYRrDmbaJeBNYxlI3htA"},{"id":"om2hap22jk1qapfbxl4410ro7","title":"百度推出 Token Exchange（词元所）大模型交易平台","summary":"百度发布 Token Exchange（词元所），一个连接 AI 模型服务商与客户的交易平台，客户可在一个入口对比模型、查看定价与性能数据并直接使用。平台上架前核验服务商资质、比对模型指纹以检测换模和虚标参数，上架后定期抽查并维护公开信用记录。上线一个月已有超100个模型资源，日均调用超50M次、700B tokens。","sourceName":"X：百度 Baidu (@Baidu_Inc)","firstParty":false,"publishedAt":"2026-11-12T07:01:37.000Z","url":"https://x.com/Baidu_Inc/status/2120773996698546653"},{"id":"hd4oj006s1360laa03idgklmj","title":"百度提出智能组织三原则","summary":"组织在 AI 时代如何演进？\n\nRobin 提出构建智能型组织的三项原则：\n- 打破角色之间的边界\n- 捕捉隐性知识，将其转化为共享资产\n- 设计闭环流程，帮助组织学习与演进\n\n展望未来，他认为岗位将收敛为两大类：构建者创造新事物，销售者培育关系并赢得信任。","sourceName":"X：百度 Baidu (@Baidu_Inc)","firstParty":false,"publishedAt":"2026-11-12T03:14:09.000Z","url":"https://x.com/Baidu_Inc/status/2120716753437393103"},{"id":"epdv6fq2z5h4uokzvt1x4rqpd","title":"百度世界大会 2026：李彦宏发布大模型交易平台“词元所”","summary":"李彦宏在百度世界大会 2026 宣布推出大模型服务平台“词元所”，定位为中立、可信的大模型交易平台，类比证券交易所汇聚模型和模型提供商。平台会对模型做准入测试并持续监测，防止偷换模型、虚标参数，同时从服务质量、兑现度、安全合规、商业履约等维度给提供方打分并给出信用评级，形成公开可查的信用档案。上线一个月供应资源数已超 100 个，日均调用 Token 数突破 7000 亿。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-12T02:52:44.170Z","url":"https://www.ithome.com/1/025/903.htm"},{"id":"uny7fg3rhwn5aosry93dhvzse","title":"李彦宏：AI 时代需要智能组织","summary":"百度 CEO 李彦宏在 Baidu World 2026 上提出，过去十年已形成芯片、云、模型、智能体四层 AI 技术栈，但要把技术进步转化为生产力，企业需超越传统层级制。他将 AI 比作新电力，认为智能组织才是 AI 时代真正释放生产力的“新工厂”，并强调充分利用 AI 能力需要 AI 原生的企业运营方式。","sourceName":"X：百度 Baidu (@Baidu_Inc)","firstParty":false,"publishedAt":"2026-11-12T02:47:33.000Z","url":"https://x.com/Baidu_Inc/status/2120710058204135615"},{"id":"clhzu7bxi8er5fjddrxv6icfq","title":"百度李彦宏：人工智能的下一幕是智能组织，组织智能将是企业最深的护城河","summary":"李彦宏在百度世界大会 2026 上提出，人工智能的下一幕是\"智能组织\"，即不同于通行科层制的 AI 原生组织体系，组织智能将成为企业最深的护城河。他将智能组织比作 AI 时代的新厂房，认为只有匹配 AI 新能力的组织方式落地，生产力才会大幅提升。他呼吁企业不能只把 AI 当个人提效工具，而要让数字员工进入销售、客服、研发、运营等环节，并提出打破岗位边界、沉淀隐性知识、设计流程闭环三条组织进化原则。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-12T01:54:29.967Z","url":"https://www.ithome.com/1/025/881.htm"},{"id":"mdhyx8f1xf5p32176bj0ia8ft","title":"百度世界2026倒计时1天：完整议程与参会指南","summary":"百度世界2026进入倒计时1天，官方发布完整议程与参会指南。活动设五大主题日，双十一AI全栈补贴每天10点开抢。","sourceName":"公众号：百度智能云（文心）","firstParty":false,"publishedAt":"2026-11-11T12:09:17.000Z","url":"https://mp.weixin.qq.com/s/d-1OmAH92hSe4JfOqPHpiw"},{"id":"s9zyu50vfwlug4nonzjc3g9m5","title":"百度世界大会2026倒计时2天","summary":"百度世界2026还有2天就要来了。\n\n想看看我们一直在做什么吗？👀\n\n11月12日观看直播 ↓","sourceName":"X：百度 Baidu (@Baidu_Inc)","firstParty":false,"publishedAt":"2026-11-10T14:00:03.000Z","url":"https://x.com/Baidu_Inc/status/2120154522928791751"},{"id":"y1yuq70v2fifocyahavqpzxyx","title":"百度世界大会 2026 直播：11 月 12 日北京举办，聚焦“智能组织”","summary":"百度世界 2026 将于 11 月 12 日在北京举办，主题为「下一幕，智能组织」。大会将聚焦“智能组织”，呈现百度在芯片、云、大模型与智能体等方面的最新进展。该大会自 2006 年起已连续举办 20 届。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-10T00:58:41.960Z","url":"https://www.ithome.com/1/024/603.htm"},{"id":"ble2u32qigzf277y27ln27z83","title":"百度世界2026倒计时3天","summary":"倒计时开始！⏳\n\n距离百度世界2026只剩3天。\n\n在X或YouTube观看直播 ↓","sourceName":"X：百度 Baidu (@Baidu_Inc)","firstParty":false,"publishedAt":"2026-11-09T14:00:00.000Z","url":"https://x.com/Baidu_Inc/status/2119792122245292217"},{"id":"lwol7ih78afft10fpv5rxphes","title":"百度世界2026大会11月12日举办","summary":"百度世界 2026 正在成形。\n\n11 月 12 日，来探索我们 6000 平方米的 AI 技术展览，面向智能化组织，重点展示 DuMate、Kooko 等。\n\n看看有哪些精彩内容 👇","sourceName":"X：百度 Baidu (@Baidu_Inc)","firstParty":false,"publishedAt":"2026-10-30T14:00:04.000Z","url":"https://x.com/Baidu_Inc/status/2116168259728974202"},{"id":"ft4cirdbt7898v70zipmpojee","title":"百度世界2026定档11月12日，6000m²展区剧透","summary":"百度世界2026定于11月12日举办，活动设有6000m²超大展区。百度智能云公众号将陆续放出更多剧透，正文同时提及深演智能与百度智能云在企业\"预测—决策—供应链\"全链路上的合作。","sourceName":"公众号：百度智能云（文心）","firstParty":false,"publishedAt":"2026-10-29T14:08:43.000Z","url":"https://mp.weixin.qq.com/s?__biz=MzA5NTQ5MzE5OQ%3D%3D&mid=2653161196&idx=2&sn=241f37e17c2bfe709702719dcf4bd730"},{"id":"z280je7mcf4sgytc03f8klw2f","title":"百度世界2026分论坛话题公布：聚焦AI组织跃迁、AI办公与知识工作、技术行业生态","summary":"百度世界2026公布10+场分论坛，聚焦AI驱动组织跃迁、AI办公与知识工作、技术·行业·生态三个方向，大会将于11月12日在北京举行。","sourceName":"公众号：百度智能云（文心）","firstParty":false,"publishedAt":"2026-10-22T11:53:54.000Z","url":"https://mp.weixin.qq.com/s?__biz=MzA5NTQ5MzE5OQ%3D%3D&mid=2653161033&idx=1&sn=5628ad1747ba084aed85021a0f7cd4c0"},{"id":"w8rq9xf9yvcejudzreox5ld1q","title":"百度世界2026设12场分论坛","summary":"让AI在整个组织内落地需要什么？\n\n我们将在11月12日百度世界2026的12场分论坛上探讨这些以及更多话题。\n\n先来看看部分议题 👇","sourceName":"X：百度 Baidu (@Baidu_Inc)","firstParty":false,"publishedAt":"2026-10-21T14:00:01.000Z","url":"https://x.com/Baidu_Inc/status/2112906756796174520"},{"id":"yijml8lqlbg47d0gup4v0r05k","title":"百度世界2026 大会主题定为「下一幕，智能组织」","summary":"百度世界2026 大会主题定为「下一幕，智能组织」，官方预告了围绕该主题的新内容。10月16日将推出「Agent来长安」环节，展示智能体从大唐不夜城走进产业生产线。","sourceName":"公众号：百度智能云（文心）","firstParty":false,"publishedAt":"2026-10-15T11:44:15.000Z","url":"https://mp.weixin.qq.com/s?__biz=MzA5NTQ5MzE5OQ%3D%3D&mid=2653160805&idx=1&sn=0d98477c83419467ef05d9827f75f25b"},{"id":"mpmb9laqfe9cnlq88dwcbjexa","title":"百度世界 2026 定档北京","summary":"百度世界 2026 将于 11 月 12 日在北京举行！🚀\n\n今年我们将探讨组织如何重新设计流程、推动创新，并大规模交付 AI 解决方案。\n\n敬请期待！","sourceName":"X：百度 Baidu (@Baidu_Inc)","firstParty":false,"publishedAt":"2026-10-14T09:27:50.000Z","url":"https://x.com/Baidu_Inc/status/2110301545887924528"},{"id":"l20zgvsrs28479ktg1rnx86my","title":"百度世界 2026 定档 11 月 12 日，将有重磅嘉宾、企业级 AI 产品集中亮相","summary":"百度世界 2026 将于 11 月 12 日在北京·国家会议中心二期举办，大会主题为“下一幕，智能组织”，官网已开启售票。官方预告本届大会将带来重磅嘉宾与企业级 AI 产品集中亮相，并设 12 场分论坛、30+ 公开课及 6000m² 展区。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-12T05:04:24.100Z","url":"https://www.ithome.com/1/011/859.htm"}]}}};
